// Use: RegulatoryChangeDrawer — Right-side drawer for pasting new regulatory circulars, triggering RAG gap analysis, and displaying impact lists.

import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { AIPanel } from "../shared/AIPanel";
import { api } from "../../lib/api";
import { Sparkles, ArrowRight, AlertTriangle, AlertCircle, CheckCircle, FileText } from "lucide-react";

interface RegulatoryChangeDrawerProps {
  open: boolean;
  onClose: () => void;
}

export function RegulatoryChangeDrawer({ open, onClose }: RegulatoryChangeDrawerProps) {
  const [circularText, setCircularText] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [result, setResult] = useState<any>(null);
  const [lastRunAt, setLastRunAt] = useState<string | null>(null);
  const navigate = useNavigate();

  const handleAnalyze = async () => {
    if (circularText.trim().length < 200) return;
    setLoading(true);
    setError(null);
    try {
      const { data } = await api.post("/api/v1/ai/compliance/regulatory-change", {
        circular_text: circularText,
      });
      setResult(data);
      setLastRunAt(new Date().toLocaleTimeString());
    } catch (err: any) {
      setError(err.response?.data?.detail || "Failed to analyze regulation. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const handleReset = () => {
    setResult(null);
    setCircularText("");
    setError(null);
  };

  // Helper to parse sections out of the AI response
  const renderSections = () => {
    if (!result || !result.response) return null;
    const text = result.response;

    // Search for a deadline date or risk keywords
    const deadlineMatch = text.match(/(deadline|by|due date|target date|before|effective from)\s*[:\-\s]*([A-Za-z0-9\s,\-\/]{6,25})/i);
    const deadlineText = deadlineMatch ? deadlineMatch[2].trim() : null;

    return (
      <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
        {/* Timeline Risk Banner */}
        <div
          style={{
            background: deadlineText ? "#FEF3C7" : "#F3F4F6",
            border: `1px solid ${deadlineText ? "#FCD34D" : "#E5E7EB"}`,
            borderRadius: "var(--radius-lg)",
            padding: 12,
            display: "flex",
            alignItems: "center",
            gap: 8,
          }}
        >
          <AlertTriangle size={16} color={deadlineText ? "#D97706" : "var(--text-muted)"} />
          <span style={{ fontSize: 13, fontWeight: 500, color: deadlineText ? "#92400E" : "var(--text-secondary)" }}>
            {deadlineText ? `Hard Deadline Found: ${deadlineText}` : "No hard deadline identified"}
          </span>
        </div>

        {/* Render raw output formatted neatly */}
        <div style={{ whiteSpace: "pre-wrap", fontSize: 13, lineHeight: 1.6, color: "var(--text-primary)" }}>
          {text}
        </div>

        {/* Quick Actions Panel */}
        <div style={{ borderTop: "1px solid var(--border)", paddingTop: 16, display: "flex", flexDirection: "column", gap: 12 }}>
          <h4 style={{ margin: 0, fontSize: 13, fontWeight: 600 }}>Suggested Actions</h4>
          <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
            <button
              className="btn btn-secondary btn-sm"
              onClick={() => {
                onClose();
                navigate("/compliance/controls");
              }}
              style={{ display: "flex", alignItems: "center", gap: 4 }}
            >
              Update Existing Controls <ArrowRight size={12} />
            </button>
            <button
              className="btn btn-secondary btn-sm"
              onClick={() => {
                onClose();
                navigate("/compliance/gaps");
              }}
              style={{ display: "flex", alignItems: "center", gap: 4 }}
            >
              Create Control Assignment <ArrowRight size={12} />
            </button>
          </div>
        </div>

        <div style={{ fontSize: 11, color: "var(--muted)", fontStyle: "italic", marginTop: 8 }}>
          Based on ComplySense knowledge base (DPDP Act 2023, ISO 27001:2022, etc.). Verify critical regulatory interpretations with your legal team.
        </div>
      </div>
    );
  };

  return (
    <AIPanel
      open={open}
      onClose={onClose}
      title="Regulatory Change Analysis"
      loading={loading}
      error={error}
      onRetry={handleAnalyze}
      hasResult={!!result}
      emptyTitle="Analyze Regulation Text"
      emptyDescription="Paste the text of a new regulation, amendment, or government circular to run a gap impact analysis."
      emptyActionLabel="Analyze Gap Impact"
      onEmptyAction={circularText.trim().length >= 200 ? handleAnalyze : undefined}
      lastRunAt={lastRunAt}
      onRegenerate={handleAnalyze}
      regenerateLoading={loading}
    >
      {!result ? (
        <div style={{ display: "flex", flexDirection: "column", gap: 12, width: "100%" }}>
          <label style={{ fontSize: 12, fontWeight: 600, color: "var(--text-secondary)" }}>
            Paste regulation text or amendment
          </label>
          <textarea
            style={{
              width: "100%",
              minHeight: 180,
              padding: 10,
              borderRadius: "var(--radius-md)",
              border: "1px solid var(--border)",
              background: "var(--surface)",
              color: "var(--text-primary)",
              fontFamily: "var(--font-sans)",
              fontSize: 13,
              resize: "vertical",
            }}
            placeholder="Paste the text of a new regulation, amendment, or government circular... (min 200 chars)"
            value={circularText}
            onChange={(e) => setCircularText(e.target.value)}
            maxLength={3000}
          />
          <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11, color: "var(--muted)" }}>
            <span>Minimum 200 characters</span>
            <span>{circularText.length} / 3000</span>
          </div>

          <button
            className="btn btn-primary"
            onClick={handleAnalyze}
            disabled={circularText.trim().length < 200 || loading}
            style={{ alignSelf: "flex-end", marginTop: 8, display: "flex", alignItems: "center", gap: 6 }}
          >
            <Sparkles size={14} />
            {loading ? "Analyzing..." : "Analyze Gap Impact"}
          </button>
        </div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <span style={{ fontSize: 12, fontWeight: 600, color: "var(--success)", display: "flex", alignItems: "center", gap: 4 }}>
              <CheckCircle size={14} /> Analysis Complete
            </span>
            <button className="btn btn-ghost btn-sm" onClick={handleReset} style={{ fontSize: 11 }}>
              Start Over
            </button>
          </div>
          {renderSections()}
        </div>
      )}
    </AIPanel>
  );
}

// Use: AIPanel — right-side drawer for AI-powered results, loading skeletons, empty/not-run states, and error handling.

import { useEffect, useState } from "react";
import { X, RefreshCw, Bot, Sparkles, AlertCircle } from "lucide-react";

interface AIPanelProps {
  open: boolean;
  onClose: () => void;
  title?: string;
  loading?: boolean;
  error?: string | null;
  onRetry?: () => void;
  footer?: React.ReactNode;
  children: React.ReactNode;

  // Specs additions
  hasResult?: boolean;
  emptyTitle?: string;
  emptyDescription?: string;
  emptyActionLabel?: string;
  onEmptyAction?: () => void;
  lastRunAt?: string | null;
  onRegenerate?: () => void;
  regenerateLoading?: boolean;
}

export function AIPanel({
  open,
  onClose,
  title = "AI Assistant",
  loading = false,
  error = null,
  onRetry,
  footer,
  children,

  hasResult = false,
  emptyTitle = "Run AI Assistant",
  emptyDescription = "Trigger AI to analyze context and generate results.",
  emptyActionLabel = "Run AI",
  onEmptyAction,
  lastRunAt = null,
  onRegenerate,
  regenerateLoading = false,
}: AIPanelProps) {
  if (!open) return null;

  return (
    <>
      {/* Overlay - clicking outside does NOT close it per spec */}
      <div className="ai-drawer-overlay" />
      <div className="ai-drawer" role="dialog" aria-label={title} aria-modal="true">
        {/* Header */}
        <div className="ai-drawer-header">
          <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
            <div
              style={{
                width: 28,
                height: 28,
                background: "linear-gradient(135deg, #2563EB, #7C3AED)",
                borderRadius: "var(--radius-md)",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
              }}
            >
              <Sparkles size={14} color="white" />
            </div>
            <span className="ai-drawer-title">{title}</span>
          </div>
          <button className="modal-close-btn" onClick={onClose} aria-label="Close AI panel">
            <X size={18} />
          </button>
        </div>

        {/* Body */}
        <div className="ai-drawer-body">
          {loading ? (
            <AIPanelSkeleton />
          ) : error ? (
            <div
              style={{
                textAlign: "center",
                padding: "32px 16px",
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                gap: 16,
              }}
            >
              <AlertCircle size={36} color="var(--critical)" />
              <div style={{ fontWeight: 600, color: "var(--text-primary)" }}>
                Failed to generate response
              </div>
              <div style={{ fontSize: 13, color: "var(--muted)", maxWidth: 300 }}>
                {error}
              </div>
              <div style={{ display: "flex", gap: 12, marginTop: 8 }}>
                {onRetry && (
                  <button className="btn btn-primary btn-sm" onClick={onRetry}>
                    <RefreshCw size={12} style={{ marginRight: 4 }} /> Retry
                  </button>
                )}
                <a
                  href="mailto:support@complysense.com"
                  className="btn btn-secondary btn-sm"
                  style={{ textDecoration: "none", display: "inline-flex", alignItems: "center" }}
                >
                  Report Issue
                </a>
              </div>
            </div>
          ) : !hasResult ? (
            <div
              style={{
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                justifyContent: "center",
                height: "100%",
                textAlign: "center",
                padding: "32px 16px",
                gap: 16,
              }}
            >
              <div
                style={{
                  width: 48,
                  height: 48,
                  background: "var(--primary-bg)",
                  color: "var(--primary)",
                  borderRadius: "50%",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                <Sparkles size={24} />
              </div>
              <div style={{ fontWeight: 600, fontSize: 16 }}>{emptyTitle}</div>
              <div style={{ fontSize: 13, color: "var(--muted)", maxWidth: 280 }}>
                {emptyDescription}
              </div>
              {onEmptyAction && (
                <button
                  className="btn btn-primary"
                  onClick={onEmptyAction}
                  style={{ marginTop: 8 }}
                >
                  {emptyActionLabel}
                </button>
              )}
            </div>
          ) : (
            children
          )}
        </div>

        {/* Footer */}
        {(footer || onRegenerate || lastRunAt) && (
          <div className="ai-drawer-footer" style={{ display: "flex", flexDirection: "column", gap: 12 }}>
            {footer}

            {(onRegenerate || lastRunAt) && (
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "space-between",
                  width: "100%",
                  borderTop: footer ? "1px solid var(--border)" : "none",
                  paddingTop: footer ? 12 : 0,
                }}
              >
                <span style={{ fontSize: 11, color: "var(--muted)" }}>
                  {lastRunAt ? `Last run: ${lastRunAt}` : ""}
                </span>
                {onRegenerate && hasResult && !loading && (
                  <button
                    className="btn btn-ghost btn-sm"
                    onClick={onRegenerate}
                    disabled={regenerateLoading}
                    style={{ fontSize: 12, padding: "4px 8px" }}
                  >
                    <RefreshCw
                      size={12}
                      style={{ marginRight: 4 }}
                      className={regenerateLoading ? "spin" : ""}
                    />
                    {regenerateLoading ? "Regenerating..." : "Regenerate"}
                  </button>
                )}
              </div>
            )}
          </div>
        )}
      </div>
    </>
  );
}

function AIPanelSkeleton() {
  const [statusMessage, setStatusMessage] = useState("Reviewing input...");

  useEffect(() => {
    const messages = [
      "Reviewing input...",
      "Checking regulatory frameworks...",
      "Preparing response..."
    ];
    let idx = 0;
    const interval = setInterval(() => {
      idx = (idx + 1) % messages.length;
      setStatusMessage(messages[idx]);
    }, 3000);
    return () => clearInterval(interval);
  }, []);

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
      {[85, 65, 90].map((w, i) => (
        <div key={i} style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          <div
            className="skeleton-cell"
            style={{ width: "40%", height: 12, borderRadius: 4 }}
          />
          <div
            className="skeleton-cell"
            style={{ width: `${w}%`, height: 48, borderRadius: 6 }}
          />
        </div>
      ))}
      <div
        style={{
          marginTop: 16,
          fontSize: 12,
          color: "var(--muted)",
          textAlign: "center",
          fontStyle: "italic",
        }}
      >
        {statusMessage}
      </div>
    </div>
  );
}

// Use: Sidebar — role-aware navigation with count badges and user menu.

import { NavLink, useNavigate } from "react-router-dom";
import {
  LayoutDashboard, Building2, ScrollText, ShieldCheck,
  FolderTree, Users, CalendarDays, FileBarChart,
  Kanban, AlertTriangle, Inbox, ClipboardList, FileText,
  CheckSquare, Bell, ShieldAlert, Siren, Settings2, Upload,
  Microscope, MessageSquare, Archive, ClipboardCheck,
  Store, CalendarX, History, BarChart3, Library, Bot,
  LogOut, User, ChevronDown, Shield,
} from "lucide-react";
import type { LucideIcon } from "lucide-react";
import { useAuthStore, useNotificationStore } from "../../store/authStore";
import { logoutApi, clearSessionStorage, roleDashboard } from "../../lib/auth";
import { useState } from "react";
import type { RoleName } from "../../types/roles";

// ─── Nav Item Definition ──────────────────────────────────────────────────────

interface NavItemDef {
  to: string;
  label: string;
  icon: LucideIcon;
  badge?: "unread" | "pending";
}

// ─── Role nav maps ────────────────────────────────────────────────────────────

const NAV_MAP: Record<RoleName, NavItemDef[]> = {
  "Super Admin": [
    { to: "/super-admin/dashboard",  label: "Dashboard",          icon: LayoutDashboard },
    { to: "/super-admin/tenants",    label: "Tenants",             icon: Building2 },
    { to: "/super-admin/audit-trail",label: "Audit Trail",         icon: ScrollText },
    { to: "/super-admin/roles",      label: "Roles & Permissions", icon: ShieldCheck },
  ],
  "Institution Admin": [
    { to: "/admin/dashboard",    label: "Dashboard",   icon: LayoutDashboard },
    { to: "/admin/departments",  label: "Departments", icon: FolderTree },
    { to: "/admin/users",        label: "Users",       icon: Users },
    { to: "/admin/calendar",     label: "Calendar",    icon: CalendarDays },
    { to: "/admin/reports",      label: "Reports",     icon: FileBarChart },
