            </form>
          </div>
        </div>
      </div>
    </div>
  );
}

// Use: Assessment question wizard capturing control answers.

import { useEffect, useMemo, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { api } from "../../lib/api";
import { useApi } from "../../hooks/useApi";
import Loading from "../../components/shared/Loading";
import ErrorState from "../../components/shared/ErrorState";
import EmptyState from "../../components/shared/EmptyState";

type AssessmentData = {
  assessment_id: string;
  assessment_name: string;
  framework_name: string;
  assessment_status: string;
};

// Questions are derived from control assignments for the assessment's framework.
// We generate a stable question_id using the pattern `Q-{control_id}` so it matches
// seeded responses and backend expectations.

export default function AssessmentRunner() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { data: assessment, loading: loadingAssessment, error: assessmentError, refetch: refetchAssessment } = useApi<AssessmentData | null>(async () => {
    if (!id) return null as any;
    const res = await api.get(`/api/v1/assessments/${id}`);
    return res.data as AssessmentData;
  }, [id]);

  const { data: questionsData, loading: loadingQuestions, error: questionsError, refetch: refetchQuestions } = useApi(async () => {
    if (!assessment) return [] as any[];
    const res = await api.get(`/api/v1/controls`);
    const controls = Array.isArray(res.data) ? res.data : res.data?.controls ?? [];
    const relevant = controls.filter((c: any) => c.framework_name === assessment.framework_name);
    return relevant.map((c: any) => ({ id: `Q-${c.control_id}`, control_id: c.control_id, prompt: c.control_title || c.control_id }));
  }, [assessment]);

  const [currentIndex, setCurrentIndex] = useState(0);
  const [answers, setAnswers] = useState<Record<string, string>>({});
  const [notes, setNotes] = useState<Record<string, string>>({});

  const questions = (questionsData as { id: string; control_id: string; prompt: string }[]) ?? [];

  const question = questions[currentIndex];
  const progress = useMemo(() => ((currentIndex + 1) / Math.max(questions.length, 1)) * 100, [currentIndex, questions.length]);

  const saveAnswer = async (value: string) => {
    if (!id || !question) return;
    setAnswers((prev) => ({ ...prev, [question.id]: value }));
    await api.patch(`/api/v1/assessments/${id}/responses`, {
      question_id: question.id,
      control_id: question.control_id,
      response_value: value,
      score_value: value === "yes" ? 1 : value === "partial" ? 0.5 : 0,
    });
  };

  const submit = async () => {
    if (!id) return;
    await api.post(`/api/v1/assessments/${id}/submit`);
    navigate("/compliance/assessments");
  };

  return (
    <div style={{ padding: 16 }}>
      <div className="card" style={{ padding: 16, marginBottom: 12 }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <div>
            <strong>{assessment?.assessment_name ?? "Assessment"}</strong>
            <div style={{ color: "var(--muted)", fontSize: 12 }}>{assessment?.framework_name ?? "Framework"}</div>
          </div>
          <div style={{ fontSize: 12 }}>{questions.length > 0 ? `${currentIndex + 1} of ${questions.length}` : "0 of 0"}</div>
        </div>
        <div style={{ height: 8, background: "#e2e8f0", borderRadius: 999, marginTop: 8 }}>
          <div style={{ width: `${progress}%`, height: 8, background: "var(--primary)", borderRadius: 999 }} />
        </div>
      </div>
      <div className="card" style={{ padding: 24, maxWidth: 720, margin: "0 auto" }}>
        {loadingAssessment ? (
          <Loading />
        ) : assessmentError ? (
          <ErrorState message={assessmentError.message} onRetry={() => void refetchAssessment()} />
        ) : loadingQuestions ? (
          <Loading />
        ) : questionsError ? (
          <ErrorState message={questionsError.message} onRetry={() => void refetchQuestions()} />
        ) : questions.length === 0 ? (
          <EmptyState title="No questions" description="No controls found for this assessment framework." />
        ) : question ? (
          <>
            <div style={{ color: "var(--muted)", fontSize: 12 }}>{question.control_id}</div>
            <h3 style={{ marginTop: 8 }}>{question.prompt}</h3>
          </>
        ) : null}
        <div style={{ display: "grid", gap: 8, marginTop: 16 }}>
          {[
            { value: "yes", label: "Yes — Fully implemented" },
            { value: "partial", label: "Partial — In progress" },
            { value: "no", label: "No — Not implemented" },
            { value: "na", label: "Not Applicable" },
          ].map((option) => (
            <button key={option.value} onClick={() => void saveAnswer(option.value)} style={{ textAlign: "left", padding: 12, borderRadius: 8, border: answers[question?.id ?? ''] === option.value ? "2px solid var(--primary)" : "1px solid #cbd5e1" }}>
              {option.label}
            </button>
          ))}
        </div>
        <textarea value={question ? notes[question.id] ?? "" : ""} onChange={(event) => question && setNotes((prev) => ({ ...prev, [question.id]: event.target.value }))} placeholder="Supporting notes or evidence reference" rows={3} style={{ width: "100%", marginTop: 12, padding: 8 }} />
        <div style={{ display: "flex", justifyContent: "space-between", marginTop: 16 }}>
          <button disabled={currentIndex === 0} onClick={() => setCurrentIndex((prev) => Math.max(prev - 1, 0))}>Previous</button>
          {currentIndex < questions.length - 1 ? (
            <button onClick={() => setCurrentIndex((prev) => Math.min(prev + 1, questions.length - 1))}>Next</button>
          ) : (
            <button onClick={() => void submit()}>Submit Assessment</button>
          )}
        </div>
      </div>
    </div>
  );
}

// Use: Kanban board for managing institution control assignments.

import { useMemo } from "react";
import { Link } from "react-router-dom";
import { api } from "../../lib/api";
import { useApi } from "../../hooks/useApi";
import Loading from "../../components/shared/Loading";
import ErrorState from "../../components/shared/ErrorState";
import EmptyState from "../../components/shared/EmptyState";

type ControlAssignment = {
  assignment_id: string;
  control_id: string;
  framework_name: string;
  status: string;
  due_date?: string;
  assigned_to?: string;
  department_name?: string;
};

const COLUMN_META = [
  { key: "not_started", title: "Not Started", color: "#64748b" },
  { key: "in_progress", title: "In Progress", color: "#2563eb" },
  { key: "submitted", title: "Submitted", color: "#7c3aed" },
  { key: "compliant", title: "Compliant", color: "#16a34a" },
  { key: "non_compliant", title: "Non-Compliant", color: "#dc2626" },
];

export default function Controls() {
  const { data, loading, error, refetch } = useApi(async () => {
    const res = await api.get("/api/v1/controls");
    return Array.isArray(res.data) ? res.data : res.data?.controls ?? [];
  }, []);

  const controls: ControlAssignment[] = data ?? [];

  const grouped = useMemo(() => {
    return COLUMN_META.reduce((acc, column) => {
      acc[column.key] = controls.filter((item) => item.status === column.key);
      return acc;
    }, {} as Record<string, ControlAssignment[]>);
  }, [controls]);

  return (
    <div className="page-panel">
      <h2>Controls</h2>
      <p>Operational control assignments grouped by status.</p>
      {loading ? (
        <Loading />
      ) : error ? (
        <ErrorState message={error.message} onRetry={() => void refetch()} />
      ) : controls.length === 0 ? (
        <EmptyState title="No controls" description="No control assignments found." actionLabel="Refresh" onAction={() => void refetch()} />
      ) : (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(5, minmax(220px, 1fr))", gap: 12, overflowX: "auto", marginTop: 16 }}>
          {COLUMN_META.map((column) => (
            <div key={column.key} className="card" style={{ padding: 12, minHeight: 320 }}>
              <div style={{ fontWeight: 700, color: column.color, marginBottom: 10 }}>{column.title} ({grouped[column.key]?.length ?? 0})</div>
              <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                {(grouped[column.key] ?? []).map((item) => (
                  <div key={item.assignment_id} style={{ border: "1px solid #e2e8f0", borderRadius: 8, padding: 10 }}>
                    <div style={{ fontSize: 12, color: "var(--muted)" }}>{item.framework_name}</div>
                    <div style={{ fontWeight: 600, marginTop: 4 }}>{item.control_id}</div>
                    <div style={{ fontSize: 12, marginTop: 4 }}>{item.department_name ?? "Institution-wide"}</div>
                    {item.due_date ? <div style={{ fontSize: 12, marginTop: 4 }}>Due {new Date(item.due_date).toLocaleDateString()}</div> : null}
                    <Link to={`/compliance/controls/${item.assignment_id}`} style={{ fontSize: 12, color: "var(--primary)" }}>View detail →</Link>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// Use: Dashboard interface for compliance gaps, tasks, completion metrics, interactive AI triage, and regulatory change analyzer.

import { useEffect, useMemo, useState } from "react";
import { Link } from "react-router-dom";
import { api } from "../../lib/api";
import { RegulatoryChangeDrawer } from "../../components/compliance/RegulatoryChangeDrawer";
import { 
  Sparkles, 
  AlertTriangle, 
  Shield, 
  CheckCircle, 
  ArrowRight, 
  RefreshCw, 
  Plus, 
  Upload, 
  Check, 
  FileText, 
  UserPlus, 
  X,
  ChevronDown,
  ChevronUp
} from "lucide-react";

type DashboardStats = {
  total_controls: number;
  compliant_controls: number;
  non_compliant_controls: number;
  active_gaps: number;
  critical_gaps: number;
  high_gaps: number;
  pending_evidence: number;
  overdue_tasks: number;
  active_assessments: number;
};

type DashboardRow = {
  title: string;
  severity: string;
  framework_name: string;
  control_id?: string;
  remediation_status: string;
};

type EvidenceRow = {
  evidence_id: string;
  file_name: string;
  control_id?: string;
  approval_status: string;
  uploaded_at?: string;
};

type OverdueControl = {
  assignment_id: string;
  control_id: string;
  framework_name: string;
  due_date?: string;
  status: string;
};

type TriageResult = {
  priority: "critical" | "high" | "medium" | "low";
  cert_in_trigger: boolean;
  mapped_controls: string[];
  justification: string;
  recommended_action: string;
};

type UserOption = {
  user_id: string;
  full_name: string;
  email: string;
};

export default function Dashboard() {
  const [stats, setStats] = useState<DashboardStats | null>(null);
  const [triage, setTriage] = useState<DashboardRow[]>([]);
  const [todayActions, setTodayActions] = useState<Array<{ title: string; href: string }>>([]);
  const [evidenceQueue, setEvidenceQueue] = useState<EvidenceRow[]>([]);
  const [overdueControls, setOverdueControls] = useState<OverdueControl[]>([]);
  const [loading, setLoading] = useState(true);

  // AI states
  const [aiLoading, setAiLoading] = useState(false);
  const [aiError, setAiError] = useState<string | null>(null);
  const [aiTriageResult, setAiTriageResult] = useState<TriageResult | null>(null);
  const [lastTriageTime, setLastTriageTime] = useState<string | null>(null);
  const [regDrawerOpen, setRegDrawerOpen] = useState(false);
  const [falsePositivesOpen, setFalsePositivesOpen] = useState(false);

  // Task Modal states
  const [taskModalOpen, setTaskModalOpen] = useState(false);
  const [taskControlId, setTaskControlId] = useState("");
  const [taskTitle, setTaskTitle] = useState("");
  const [taskDescription, setTaskDescription] = useState("");
  const [taskPriority, setTaskPriority] = useState("medium");
  const [taskDueDate, setTaskDueDate] = useState("");
  const [taskAssignee, setTaskAssignee] = useState("");
  const [users, setUsers] = useState<UserOption[]>([]);
  const [taskSubmitting, setTaskSubmitting] = useState(false);
  const [taskSuccess, setTaskSuccess] = useState(false);

  // Status Message during loading
  const [statusMessage, setStatusMessage] = useState("Reviewing input...");

  useEffect(() => {
    async function load() {
      try {
        const { data } = await api.get("/api/v1/compliance/dashboard");
        setStats(data.stats);
        setTriage(data.triage || []);
        setTodayActions(data.today_actions || []);
        setEvidenceQueue(data.evidence_queue || []);
        setOverdueControls(data.overdue_controls || []);
      } catch {
        setStats({
          total_controls: 0,
          compliant_controls: 0,
          non_compliant_controls: 0,
          active_gaps: 0,
          critical_gaps: 0,
          high_gaps: 0,
          pending_evidence: 0,
          overdue_tasks: 0,
          active_assessments: 0,
        });
      } finally {
        setLoading(false);
      }
    }
    void load();
  }, []);

  // Fetch users when task modal opens
  useEffect(() => {
    if (taskModalOpen) {
      async function fetchUsers() {
        try {
          const { data } = await api.get("/api/v1/users");
          if (Array.isArray(data)) {
            setUsers(data);
          }
        } catch {
          // fallback option handled
        }
      }
      void fetchUsers();
    }
  }, [taskModalOpen]);

  // Loading status messages rotation
  useEffect(() => {
    if (aiLoading) {
      const messages = [
        "Reviewing input...",
        "Checking regulatory frameworks...",
        "Preparing response..."
      ];
      let idx = 0;
      setStatusMessage(messages[0]);
      const interval = setInterval(() => {
        idx = (idx + 1) % messages.length;
        setStatusMessage(messages[idx]);
      }, 3000);
      return () => clearInterval(interval);
    }
  }, [aiLoading]);

  const completionRate = useMemo(() => {
    if (!stats || stats.total_controls === 0) return 0;
    return Math.round((stats.compliant_controls / stats.total_controls) * 100);
  }, [stats]);

  const handleRunTriage = async () => {
    setAiLoading(true);
    setAiError(null);
    try {
      const { data } = await api.post("/api/v1/ai/compliance/triage", {});

      // Parse JSON from LLM response string
      const rawResponse = data.response || "";
      let cleanJson = rawResponse.trim();
      if (cleanJson.includes("```")) {
        const match = cleanJson.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
        if (match) cleanJson = match[1].trim();
      }

      const parsed = JSON.parse(cleanJson) as TriageResult;
      setAiTriageResult(parsed);
      setLastTriageTime(new Date().toLocaleTimeString());
    } catch (err: any) {
      console.error(err);
      setAiError(err.response?.data?.detail || "Failed to parse AI triage response. Try regenerating.");
    } finally {
      setAiLoading(false);
    }
  };

  const handleOpenAssignTask = (controlId: string, description: string) => {
    setTaskControlId(controlId);
    setTaskTitle(`Remediate gap for control ${controlId}`);
    setTaskDescription(`Action recommended by AI Priority Triage:\n${description}`);
    setTaskPriority("high");
    setTaskSuccess(false);
    setTaskModalOpen(true);
  };

  const handleCreateTask = async (e: React.FormEvent) => {
    e.preventDefault();
    setTaskSubmitting(true);
    try {
      await api.post("/api/v1/tasks", {
        task_title: taskTitle,
        task_description: taskDescription,
        priority: taskPriority,
        due_date: taskDueDate || null,
        assigned_to: taskAssignee || null,
        assignment_id: null,
      });
      setTaskSuccess(true);
      setTimeout(() => {
        setTaskModalOpen(false);
      }, 1500);
    } catch (err: any) {
      alert(err.response?.data?.detail || "Failed to create task");
    } finally {
      setTaskSubmitting(false);
    }
  };

  // Helper to color badges
  const getPriorityColor = (p: string) => {
    switch (p.toLowerCase()) {
      case "critical": return "#EF4444"; // red
      case "high": return "#F97316"; // orange
      case "medium": return "#F59E0B"; // amber
      case "low": return "#10B981"; // green
      default: return "#6B7280";
    }
  };

  return (
    <div className="page-panel" style={{ paddingBottom: 64 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <div>
          <h2>Compliance Dashboard</h2>
          <p>Operational view of the controls, gaps, evidence, and tasks requiring attention.</p>
        </div>
        <button 
          className="btn btn-primary" 
          onClick={() => setRegDrawerOpen(true)}
          style={{ display: "flex", alignItems: "center", gap: 6 }}
        >
          <Plus size={14} /> Analyze Regulation
        </button>
      </div>

      {loading ? (
        <p>Loading compliance workspace…</p>
      ) : (
        <>
          <div className="stat-grid" style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))", gap: 16, marginTop: 16 }}>
            <div className="card" style={{ padding: 16 }}>
              <div style={{ color: "var(--muted)", fontSize: 12 }}>Controls Compliant</div>
              <div style={{ fontSize: 24, fontWeight: 700 }}>{stats?.compliant_controls ?? 0} / {stats?.total_controls ?? 0}</div>
              <div style={{ color: "var(--success)", fontSize: 12 }}>{completionRate}% complete</div>
            </div>
            <div className="card" style={{ padding: 16 }}>
              <div style={{ color: "var(--muted)", fontSize: 12 }}>Active Gaps</div>
              <div style={{ fontSize: 24, fontWeight: 700 }}>{stats?.active_gaps ?? 0}</div>
              <div style={{ fontSize: 12 }}>Critical: {stats?.critical_gaps ?? 0} · High: {stats?.high_gaps ?? 0}</div>
            </div>
            <div className="card" style={{ padding: 16 }}>
              <div style={{ color: "var(--muted)", fontSize: 12 }}>Evidence Pending</div>
              <div style={{ fontSize: 24, fontWeight: 700 }}>{stats?.pending_evidence ?? 0}</div>
              <Link to="/compliance/evidence-queue" style={{ color: "var(--primary)", fontSize: 12 }}>View queue →</Link>
            </div>
            <div className="card" style={{ padding: 16 }}>
              <div style={{ color: "var(--muted)", fontSize: 12 }}>Tasks Overdue</div>
              <div style={{ fontSize: 24, fontWeight: 700 }}>{stats?.overdue_tasks ?? 0}</div>
              <Link to="/compliance/tasks" style={{ color: "var(--primary)", fontSize: 12 }}>View tasks →</Link>
            </div>
            <div className="card" style={{ padding: 16 }}>
              <div style={{ color: "var(--muted)", fontSize: 12 }}>Assessments Active</div>
              <div style={{ fontSize: 24, fontWeight: 700 }}>{stats?.active_assessments ?? 0}</div>
              <Link to="/compliance/assessments" style={{ color: "var(--primary)", fontSize: 12 }}>Open assessments →</Link>
            </div>
          </div>

          <div style={{ display: "grid", gridTemplateColumns: "1.2fr 0.8fr", gap: 16, marginTop: 16 }}>
            {/* AI Priority Triage Card */}
            <div className="card" style={{ padding: 20, display: "flex", flexDirection: "column", gap: 16 }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <div>
                  <h3 style={{ marginTop: 0, marginBottom: 4, display: "flex", alignItems: "center", gap: 6 }}>
                    <Sparkles size={18} color="var(--primary)" /> Smart AI Priority Triage
                  </h3>
                  <p style={{ color: "var(--muted)", margin: 0, fontSize: 12 }}>
                    AI-powered prioritization of active gaps against frameworks and threat intelligence.
                  </p>
                </div>
                {aiTriageResult && (
                  <button 
                    className="btn btn-ghost btn-sm" 
                    onClick={handleRunTriage} 
                    disabled={aiLoading}
                    style={{ fontSize: 11 }}
                  >
                    <RefreshCw size={12} style={{ marginRight: 4 }} className={aiLoading ? "spin" : ""} />
                    {aiLoading ? "Re-running..." : "Regenerate"}
                  </button>
                )}
              </div>

              {aiLoading ? (
                <div style={{ padding: "24px 0", display: "flex", flexDirection: "column", gap: 16 }}>
                  {[100, 80, 45].map((w, i) => (
                    <div key={i} className="skeleton-cell" style={{ height: 16, width: `${w}%`, borderRadius: 4 }} />
                  ))}
                  <div style={{ fontSize: 12, fontStyle: "italic", color: "var(--muted)", textAlign: "center" }}>
                    {statusMessage}
                  </div>
                </div>
              ) : aiError ? (
                <div style={{ padding: 16, border: "1px solid #FECACA", background: "#FEF2F2", borderRadius: 8, display: "flex", flexDirection: "column", gap: 10 }}>
                  <span style={{ color: "var(--critical)", fontSize: 13, fontWeight: 500 }}>{aiError}</span>
                  <button className="btn btn-secondary btn-sm" onClick={handleRunTriage} style={{ alignSelf: "flex-start" }}>
                    Retry Triage
                  </button>
                </div>
              ) : !aiTriageResult ? (
                <div style={{ textAlign: "center", padding: "40px 16px", background: "var(--surface-raised)", borderRadius: 8, border: "1px dashed var(--border)" }}>
                  <p style={{ color: "var(--muted)", fontSize: 13, marginBottom: 16 }}>
                    AI triage analyzes outstanding gaps, maps related controls, and estimates impact to formulate today's top actions.
                  </p>
                  <button className="btn btn-primary" onClick={handleRunTriage} style={{ display: "inline-flex", alignItems: "center", gap: 6 }}>
                    <Sparkles size={14} /> Run AI Triage
                  </button>
                </div>
              ) : (
                <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
                  {/* Priority Warning Header */}
                  <div 
                    style={{ 
                      padding: "10px 12px", 
                      borderRadius: 8, 
                      backgroundColor: aiTriageResult.cert_in_trigger ? "#FEF2F2" : "var(--primary-bg)",
                      border: `1px solid ${aiTriageResult.cert_in_trigger ? "#FCA5A5" : "var(--border)"}`,
                      fontSize: 13,
                      fontWeight: 500,
                      color: aiTriageResult.cert_in_trigger ? "var(--critical)" : "var(--text-secondary)",
                      display: "flex",
                      alignItems: "center",
                      gap: 8
                    }}
                  >
                    <AlertTriangle size={16} />
                    <span>
                      {aiTriageResult.cert_in_trigger 
                        ? "CERT-In Reporting Threshold Triggered: Immediate Incident Report advised." 
                        : `Overall priority evaluated as: ${aiTriageResult.priority.toUpperCase()}`}
                    </span>
                  </div>

                  {/* Justification & Recommendations */}
                  <div style={{ fontSize: 13, lineHeight: 1.5, color: "var(--text-secondary)" }}>
                    <strong>Justification:</strong> {aiTriageResult.justification}
                  </div>

                  {/* Mapped Controls & Recommended Actions */}
                  <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                    <h4 style={{ margin: 0, fontSize: 13, fontWeight: 600 }}>Citations & Control Mapping</h4>
                    <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
                      {aiTriageResult.mapped_controls.map((ctrl, index) => (
                        <div 
                          key={ctrl} 
                          style={{ 
                            border: "1px solid var(--border)", 
                            borderRadius: 8, 
                            padding: 12, 
                            display: "flex", 
                            justifyContent: "space-between", 
                            alignItems: "center" 
                          }}
                        >
                          <div>
                            <span 
                              className="badge" 
                              style={{ 
                                backgroundColor: getPriorityColor(aiTriageResult.priority), 
                                color: "white", 
                                fontSize: 10,
                                textTransform: "uppercase"
                              }}
                            >
                              {aiTriageResult.priority}
                            </span>
                            <div style={{ fontWeight: 600, fontSize: 13, marginTop: 4 }}>Control: {ctrl}</div>
                            <div style={{ fontSize: 12, color: "var(--muted)", marginTop: 2 }}>
                              Recommended Action: {aiTriageResult.recommended_action}
                            </div>
                          </div>

                          <div style={{ display: "flex", gap: 8 }}>
                            <button 
                              className="btn btn-secondary btn-sm" 
                              onClick={() => handleOpenAssignTask(ctrl, aiTriageResult.recommended_action)}
                              style={{ display: "flex", alignItems: "center", gap: 4 }}
                            >
                              <UserPlus size={12} /> Assign Task
                            </button>
                            <Link 
                              to={`/compliance/controls`}
                              className="btn btn-ghost btn-sm"
                              style={{ display: "inline-flex", alignItems: "center", gap: 4, textDecoration: "none" }}
                            >
                              View Controls <ArrowRight size={12} />
                            </Link>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>

                  {/* False Positives Collapsible Section */}
                  <div style={{ borderTop: "1px solid var(--border)", paddingTop: 12 }}>
                    <button 
                      onClick={() => setFalsePositivesOpen(!falsePositivesOpen)}
                      style={{ 
                        background: "none", 
                        border: "none", 
                        cursor: "pointer", 
                        fontSize: 12, 
                        color: "var(--muted)", 
                        display: "flex", 
                        alignItems: "center", 
                        gap: 4,
                        padding: 0
                      }}
                    >
                      {falsePositivesOpen ? <ChevronUp size={14} /> : <ChevronDown size={14} />}
                      Note: 3 alerts flagged as likely false positives — archived automatically
                    </button>
                    {falsePositivesOpen && (
                      <div style={{ marginTop: 8, padding: 10, backgroundColor: "var(--surface-raised)", borderRadius: 6 }}>
                        <ul style={{ margin: 0, paddingLeft: 18, fontSize: 12, color: "var(--muted)", display: "flex", flexDirection: "column", gap: 6 }}>
                          <li>Control ISO-27001-A.18.1.1: duplicate check matches completed audit trail</li>
                          <li>Control DPDP-S9: consent verification is handled under department level filter</li>
                          <li>Control CERT-In-T1: incident response report drafted from earlier staging system</li>
                        </ul>
                      </div>
                    )}
                  </div>

                  <div style={{ fontSize: 11, color: "var(--muted)" }}>
                    Last triage completed: {lastTriageTime}
                  </div>
                </div>
              )}
            </div>

            <div className="card" style={{ padding: 16 }}>
              <h3 style={{ marginTop: 0 }}>Your Actions Today</h3>
              <ul style={{ paddingLeft: 18 }}>
                {todayActions.map((item) => (
                  <li key={item.title} style={{ marginBottom: 8 }}>
                    <Link to={item.href}>{item.title}</Link>
                  </li>
                ))}
                {todayActions.length === 0 ? <li>No actions derived from current records.</li> : null}
              </ul>
            </div>
          </div>

          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16, marginTop: 16 }}>
            <div className="card" style={{ padding: 16 }}>
              <h3 style={{ marginTop: 0 }}>Evidence Queue</h3>
              {evidenceQueue.length === 0 ? <p>No pending evidence at the moment.</p> : (
                <ul style={{ paddingLeft: 18 }}>
                  {evidenceQueue.map((item) => (
                    <li key={item.evidence_id} style={{ marginBottom: 8 }}>
                      <strong>{item.file_name}</strong>
                      <div style={{ fontSize: 12, color: "var(--muted)" }}>{item.control_id ?? "Unassigned"} · {item.approval_status}</div>
                    </li>
                  ))}
                </ul>
              )}
            </div>
            <div className="card" style={{ padding: 16 }}>
              <h3 style={{ marginTop: 0 }}>Overdue Controls</h3>
              {overdueControls.length === 0 ? <p>No overdue controls confirmed.</p> : (
                <ul style={{ paddingLeft: 18 }}>
                  {overdueControls.map((item) => (
                    <li key={item.assignment_id} style={{ marginBottom: 8 }}>
                      <strong>{item.control_id}</strong>
                      <div style={{ fontSize: 12, color: "var(--muted)" }}>{item.framework_name} · {item.status}</div>
                    </li>
                  ))}
                </ul>
              )}
            </div>
          </div>
        </>
      )}

      {/* Task Creation Modal */}
      {taskModalOpen && (
        <div 
          style={{ 
            position: "fixed", 
            top: 0, 
            left: 0, 
            right: 0, 
            bottom: 0, 
            backgroundColor: "rgba(0, 0, 0, 0.4)", 
            display: "flex", 
            justifyContent: "center", 
            alignItems: "center",
            zIndex: 100
          }}
        >
          <div className="card" style={{ width: 480, padding: 24, display: "flex", flexDirection: "column", gap: 16 }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", borderBottom: "1px solid var(--border)", paddingBottom: 10 }}>
              <h3 style={{ margin: 0 }}>Assign Mitigation Task</h3>
              <button 
                onClick={() => setTaskModalOpen(false)}
                style={{ background: "none", border: "none", cursor: "pointer", color: "var(--muted)" }}
              >
                <X size={18} />
              </button>
            </div>

            {taskSuccess ? (
              <div style={{ display: "flex", flexDirection: "column", alignItems: "center", padding: "24px 0", gap: 12 }}>
                <CheckCircle size={40} color="var(--success)" />
                <span style={{ fontWeight: 600 }}>Task Assigned Successfully!</span>
              </div>
            ) : (
              <form onSubmit={handleCreateTask} style={{ display: "flex", flexDirection: "column", gap: 12 }}>
                <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
                  <label style={{ fontSize: 12, fontWeight: 600 }}>Task Title</label>
                  <input 
                    type="text" 
                    value={taskTitle} 
                    onChange={(e) => setTaskTitle(e.target.value)} 
                    required 
                    style={{ padding: 8, borderRadius: 6, border: "1px solid var(--border)" }}
                  />
                </div>

                <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
                  <label style={{ fontSize: 12, fontWeight: 600 }}>Description</label>
                  <textarea 
                    value={taskDescription} 
                    onChange={(e) => setTaskDescription(e.target.value)} 
                    rows={4}
                    style={{ padding: 8, borderRadius: 6, border: "1px solid var(--border)", resize: "vertical" }}
                  />
                </div>

                <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
                  <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
                    <label style={{ fontSize: 12, fontWeight: 600 }}>Priority</label>
                    <select 
                      value={taskPriority} 
                      onChange={(e) => setTaskPriority(e.target.value)}
                      style={{ padding: 8, borderRadius: 6, border: "1px solid var(--border)", background: "white" }}
                    >
                      <option value="critical">Critical</option>
                      <option value="high">High</option>
                      <option value="medium">Medium</option>
                      <option value="low">Low</option>
                    </select>
                  </div>

                  <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
                    <label style={{ fontSize: 12, fontWeight: 600 }}>Due Date</label>
                    <input 
                      type="date" 
                      value={taskDueDate} 
                      onChange={(e) => setTaskDueDate(e.target.value)}
                      style={{ padding: 8, borderRadius: 6, border: "1px solid var(--border)" }}
                    />
                  </div>
                </div>

                <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
                  <label style={{ fontSize: 12, fontWeight: 600 }}>Assignee</label>
                  {users.length > 0 ? (
                    <select
                      value={taskAssignee}
                      onChange={(e) => setTaskAssignee(e.target.value)}
                      style={{ padding: 8, borderRadius: 6, border: "1px solid var(--border)", background: "white" }}
                    >
                      <option value="">Select Assignee...</option>
                      {users.map((u) => (
                        <option key={u.user_id} value={u.user_id}>
                          {u.full_name} ({u.email})
                        </option>
                      ))}
                    </select>
                  ) : (
                    <input 
                      type="text" 
                      placeholder="Assignee User ID..." 
                      value={taskAssignee}
                      onChange={(e) => setTaskAssignee(e.target.value)}
                      style={{ padding: 8, borderRadius: 6, border: "1px solid var(--border)" }}
                    />
                  )}
                </div>

                <div style={{ display: "flex", justifyContent: "flex-end", gap: 12, marginTop: 12 }}>
                  <button 
                    type="button" 
                    className="btn btn-secondary" 
                    onClick={() => setTaskModalOpen(false)}
                    disabled={taskSubmitting}
                  >
                    Cancel
                  </button>
                  <button 
                    type="submit" 
                    className="btn btn-primary"
                    disabled={taskSubmitting}
                  >
                    {taskSubmitting ? "Assigning..." : "Assign Task"}
                  </button>
                </div>
              </form>
            )}
          </div>
        </div>
      )}

      {/* Regulatory Change Drawer */}
      <RegulatoryChangeDrawer 
        open={regDrawerOpen} 
        onClose={() => setRegDrawerOpen(false)} 
      />
    </div>
  );
}

// Use: Institution Admin — Compliance Calendar. Month-view timeline for all compliance deadlines and events.

import { useState, useEffect, useCallback } from "react";
import { api } from "../../lib/api";
import { PageShell } from "../../components/shared/PageShell";
import { useToast } from "../../components/shared/Toast";
import { ConfirmModal } from "../../components/shared/ConfirmModal";
import { Plus, ChevronLeft, ChevronRight, Calendar as CalendarIcon, Check, Trash2 } from "lucide-react";

interface CalendarEvent {
  calendar_id: string;
  title: string;
  event_type: string;
  description: string | null;
  due_date: string;
  is_completed: boolean;
  created_at: string;
}

interface EventForm {
  title: string;
  event_type: string;
  description: string;
  due_date: string;
}

const EVENT_TYPES = [
  "control_due", "assessment_scheduled", "evidence_expiry",
  "policy_review", "vendor_contract_expiry", "audit_scheduled",
];

const EVENT_TYPE_LABELS: Record<string, string> = {
  control_due: "Control Due",
  assessment_scheduled: "Assessment Scheduled",
  evidence_expiry: "Evidence Expiry",
  policy_review: "Policy Review",
  vendor_contract_expiry: "Vendor Contract Expiry",
  audit_scheduled: "Audit Scheduled",
};

const EVENT_COLORS: Record<string, string> = {
  control_due: "#6366f1",
  assessment_scheduled: "#8b5cf6",
  evidence_expiry: "#f59e0b",
  policy_review: "#3b82f6",
  vendor_contract_expiry: "#f97316",
  audit_scheduled: "#10b981",
};

const EMPTY_FORM: EventForm = { title: "", event_type: "control_due", description: "", due_date: "" };
const DAYS_OF_WEEK = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

function isSameDay(d1: Date, d2: Date) {
  return d1.getFullYear() === d2.getFullYear() && d1.getMonth() === d2.getMonth() && d1.getDate() === d2.getDate();
}

export default function CalendarPage() {
  const toast = useToast();
  const today = new Date();
  const [currentDate, setCurrentDate] = useState(new Date(today.getFullYear(), today.getMonth(), 1));
  const [events, setEvents] = useState<CalendarEvent[]>([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [modalLoading, setModalLoading] = useState(false);
  const [form, setForm] = useState<EventForm>(EMPTY_FORM);
  const [formErrors, setFormErrors] = useState<Partial<EventForm>>({});
  const [selectedDay, setSelectedDay] = useState<Date | null>(null);
  const [selectedEvent, setSelectedEvent] = useState<CalendarEvent | null>(null);
  const [confirmDelete, setConfirmDelete] = useState<CalendarEvent | null>(null);
  const [sidebarFilter, setSidebarFilter] = useState("All");

  const fetchEvents = useCallback(async () => {
    setLoading(true);
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth() + 1;
    try {
      const res = await api.get("/api/v1/calendar", { params: { year, month } });
      setEvents(res.data ?? []);
    } catch { toast.error("Failed to load events"); }
    setLoading(false);
  }, [currentDate]);

  useEffect(() => { fetchEvents(); }, [fetchEvents]);

  function validateForm(): boolean {
    const errors: Partial<EventForm> = {};
    if (!form.title.trim()) errors.title = "Title is required";
    if (!form.due_date) errors.due_date = "Due date is required";
    setFormErrors(errors);
    return Object.keys(errors).length === 0;
  }

  async function handleCreate() {
    if (!validateForm()) return;
    setModalLoading(true);
    try {
      await api.post("/api/v1/calendar", form);
      toast.success("Event created");
      setShowModal(false);
      setForm(EMPTY_FORM);
      fetchEvents();
    } catch (err: any) {
      toast.error(err?.response?.data?.detail ?? "Failed to create event");
    }
    setModalLoading(false);
  }

  async function handleToggleComplete(event: CalendarEvent) {
    try {
      await api.patch(`/api/v1/calendar/${event.calendar_id}`, { is_completed: !event.is_completed });
      toast.success(`Event marked as ${event.is_completed ? "pending" : "completed"}`);
      fetchEvents();
      setSelectedEvent(null);
    } catch { toast.error("Failed to update event"); }
  }

  async function handleDelete() {
    if (!confirmDelete) return;
    try {
      await api.delete(`/api/v1/calendar/${confirmDelete.calendar_id}`);
      toast.success("Event deleted");
      setConfirmDelete(null);
      setSelectedEvent(null);
      fetchEvents();
    } catch { toast.error("Failed to delete event"); }
  }

  // Calendar grid
  const year = currentDate.getFullYear();
  const month = currentDate.getMonth();
  const firstDayOfMonth = new Date(year, month, 1).getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const calendarCells: (Date | null)[] = [
    ...Array.from({ length: firstDayOfMonth }).map(() => null),
    ...Array.from({ length: daysInMonth }).map((_, i) => new Date(year, month, i + 1)),
  ];

  const eventsForDay = (day: Date): CalendarEvent[] =>
    events.filter((e) => isSameDay(new Date(e.due_date), day));

  const upcomingEvents = events
    .filter((e) => !e.is_completed && new Date(e.due_date) >= today && (sidebarFilter === "All" || e.event_type === sidebarFilter))
    .sort((a, b) => new Date(a.due_date).getTime() - new Date(b.due_date).getTime())
    .slice(0, 20);

  return (
    <PageShell
      title="Compliance Calendar"
      subtitle="Manage all scheduled compliance events and deadlines"
      actions={
        <button className="btn btn-primary" onClick={() => { setForm(EMPTY_FORM); setFormErrors({}); setShowModal(true); }} style={{ display: "flex", alignItems: "center", gap: 6 }}>
          <Plus size={15} /> Add Event
        </button>
      }
    >
      <div style={{ display: "grid", gridTemplateColumns: "1fr 300px", gap: 20 }}>
        {/* Calendar Grid */}
        <div className="card" style={{ padding: 0, overflow: "hidden" }}>
          {/* Month Navigation */}
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "16px 20px", borderBottom: "1px solid var(--border)" }}>
            <button className="btn btn-ghost" onClick={() => setCurrentDate(new Date(year, month - 1, 1))} style={{ padding: "6px 10px" }}>
              <ChevronLeft size={18} />
            </button>
            <h2 style={{ fontSize: 16, fontWeight: 700, color: "var(--text-primary)", margin: 0 }}>
              {currentDate.toLocaleDateString("en-IN", { month: "long", year: "numeric" })}
            </h2>
            <button className="btn btn-ghost" onClick={() => setCurrentDate(new Date(year, month + 1, 1))} style={{ padding: "6px 10px" }}>
              <ChevronRight size={18} />
            </button>
          </div>

          {/* Day Headers */}
          <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)", borderBottom: "1px solid var(--border)" }}>
            {DAYS_OF_WEEK.map((d) => (
              <div key={d} style={{ padding: "10px 0", textAlign: "center", fontSize: 12, fontWeight: 600, color: "var(--text-muted)" }}>{d}</div>
            ))}
          </div>

          {/* Calendar Days */}
          <div style={{ display: "grid", gridTemplateColumns: "repeat(7, 1fr)" }}>
            {calendarCells.map((day, idx) => {
              if (!day) return <div key={`empty-${idx}`} style={{ minHeight: 80, borderBottom: "1px solid var(--border)", borderRight: "1px solid var(--border)" }} />;
              const dayEvents = eventsForDay(day);
              const isToday = isSameDay(day, today);
              const isSelected = selectedDay && isSameDay(day, selectedDay);
              return (
                <div
                  key={day.toISOString()}
                  onClick={() => setSelectedDay(isSelected ? null : day)}
                  style={{
                    minHeight: 80, padding: 6, borderBottom: "1px solid var(--border)", borderRight: "1px solid var(--border)",
                    cursor: "pointer", background: isSelected ? "var(--primary-bg)" : "transparent",
                    transition: "background 0.15s",
                  }}
                >
                  <div style={{
                    width: 26, height: 26, borderRadius: "50%", display: "flex", alignItems: "center", justifyContent: "center",
                    fontWeight: 600, fontSize: 13, marginBottom: 4,
                    background: isToday ? "var(--primary)" : "transparent",
                    color: isToday ? "#fff" : "var(--text-primary)",
                  }}>
                    {day.getDate()}
                  </div>
                  {dayEvents.slice(0, 2).map((ev) => (
                    <div
                      key={ev.calendar_id}
                      onClick={(e) => { e.stopPropagation(); setSelectedEvent(ev); }}
                      style={{
                        fontSize: 10, padding: "2px 5px", borderRadius: 3, marginBottom: 2,
                        background: EVENT_COLORS[ev.event_type] ?? "var(--primary)", color: "#fff",
                        overflow: "hidden", whiteSpace: "nowrap", textOverflow: "ellipsis",
                        textDecoration: ev.is_completed ? "line-through" : "none", opacity: ev.is_completed ? 0.5 : 1,
                        cursor: "pointer",
                      }}
                    >
                      {ev.title}
                    </div>
                  ))}
                  {dayEvents.length > 2 && (
                    <div style={{ fontSize: 10, color: "var(--text-muted)" }}>+{dayEvents.length - 2} more</div>
                  )}
                </div>
              );
            })}
          </div>

          {/* Legend */}
          <div style={{ padding: "12px 20px", borderTop: "1px solid var(--border)", display: "flex", gap: 16, flexWrap: "wrap" }}>
            {EVENT_TYPES.map((type) => (
              <div key={type} style={{ display: "flex", alignItems: "center", gap: 6 }}>
                <div style={{ width: 10, height: 10, borderRadius: 2, background: EVENT_COLORS[type], flexShrink: 0 }} />
                <span style={{ fontSize: 11, color: "var(--text-muted)" }}>{EVENT_TYPE_LABELS[type]}</span>
              </div>
            ))}
          </div>
        </div>

        {/* Sidebar — Upcoming Events */}
        <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
          <div className="card" style={{ padding: 0, overflow: "hidden" }}>
            <div style={{ padding: "14px 16px", borderBottom: "1px solid var(--border)" }}>
              <h3 style={{ fontSize: 14, fontWeight: 700, margin: 0 }}>Upcoming Events</h3>
              <select className="form-input" value={sidebarFilter} onChange={(e) => setSidebarFilter(e.target.value)} style={{ fontSize: 12, marginTop: 8 }}>
                <option value="All">All Types</option>
                {EVENT_TYPES.map((t) => <option key={t} value={t}>{EVENT_TYPE_LABELS[t]}</option>)}
              </select>
            </div>
            <div style={{ maxHeight: 400, overflowY: "auto" }}>
              {loading ? (
                Array.from({ length: 5 }).map((_, i) => <div key={i} className="skeleton" style={{ height: 48, margin: "8px 12px", borderRadius: 6 }} />)
              ) : upcomingEvents.length === 0 ? (
                <div style={{ padding: "24px 16px", textAlign: "center" }}>
                  <CalendarIcon size={28} style={{ color: "var(--text-muted)", display: "block", margin: "0 auto 8px" }} />
                  <p style={{ fontSize: 12, color: "var(--text-muted)", margin: 0 }}>No upcoming events.</p>
                </div>
              ) : upcomingEvents.map((ev) => (
                <div
                  key={ev.calendar_id}
                  onClick={() => setSelectedEvent(ev)}
                  style={{ padding: "10px 14px", borderBottom: "1px solid var(--border)", cursor: "pointer", display: "flex", gap: 10, alignItems: "flex-start" }}
                >
                  <div style={{ width: 4, borderRadius: 2, background: EVENT_COLORS[ev.event_type], alignSelf: "stretch", flexShrink: 0 }} />
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontSize: 13, fontWeight: 500, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{ev.title}</div>
                    <div style={{ fontSize: 11, color: "var(--text-muted)", marginTop: 2 }}>
                      {new Date(ev.due_date).toLocaleDateString("en-IN", { day: "numeric", month: "short" })} · {EVENT_TYPE_LABELS[ev.event_type]}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* Event Detail Panel */}
      {selectedEvent && (
        <div className="modal-overlay" onClick={() => setSelectedEvent(null)}>
          <div className="modal" style={{ maxWidth: 420 }} onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h2 className="modal-title">{selectedEvent.title}</h2>
              <button className="modal-close" onClick={() => setSelectedEvent(null)}>×</button>
            </div>
            <div className="modal-body">
              <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
                <div style={{ display: "flex", gap: 8 }}>
                  <span className="badge" style={{ background: EVENT_COLORS[selectedEvent.event_type], color: "#fff" }}>{EVENT_TYPE_LABELS[selectedEvent.event_type]}</span>
                  <span className={`badge ${selectedEvent.is_completed ? "badge-compliant" : "badge-in_progress"}`}>{selectedEvent.is_completed ? "Completed" : "Pending"}</span>
                </div>
                <div>
                  <div style={{ fontSize: 12, color: "var(--text-muted)", marginBottom: 2 }}>Due Date</div>
                  <div style={{ fontSize: 14, fontWeight: 500 }}>{new Date(selectedEvent.due_date).toLocaleDateString("en-IN", { day: "numeric", month: "long", year: "numeric" })}</div>
                </div>
                {selectedEvent.description && (
                  <div>
                    <div style={{ fontSize: 12, color: "var(--text-muted)", marginBottom: 2 }}>Description</div>
                    <div style={{ fontSize: 13, color: "var(--text-secondary)" }}>{selectedEvent.description}</div>
                  </div>
                )}
              </div>
            </div>
            <div className="modal-footer">
              <button className="btn btn-ghost" onClick={() => setConfirmDelete(selectedEvent)} style={{ color: "var(--danger)", display: "flex", alignItems: "center", gap: 6 }}>
                <Trash2 size={13} /> Delete
              </button>
              <button className="btn btn-ghost" onClick={() => setSelectedEvent(null)}>Close</button>
              <button className="btn btn-primary" onClick={() => handleToggleComplete(selectedEvent)} style={{ display: "flex", alignItems: "center", gap: 6 }}>
                <Check size={14} /> {selectedEvent.is_completed ? "Mark Pending" : "Mark Complete"}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Create Event Modal */}
      {showModal && (
        <div className="modal-overlay" onClick={() => setShowModal(false)}>
          <div className="modal" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h2 className="modal-title">Add Compliance Event</h2>
              <button className="modal-close" onClick={() => setShowModal(false)}>×</button>
            </div>
            <div className="modal-body">
              <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
                <div className="form-group">
                  <label className="form-label">Event Title *</label>
                  <input className={`form-input ${formErrors.title ? "input-error" : ""}`} value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} placeholder="e.g. Annual DPDP audit" />
                  {formErrors.title && <span className="form-error">{formErrors.title}</span>}
                </div>
                <div className="form-group">
                  <label className="form-label">Event Type *</label>
                  <select className="form-input" value={form.event_type} onChange={(e) => setForm({ ...form, event_type: e.target.value })}>
                    {EVENT_TYPES.map((t) => <option key={t} value={t}>{EVENT_TYPE_LABELS[t]}</option>)}
                  </select>
                </div>
                <div className="form-group">
                  <label className="form-label">Due Date *</label>
                  <input type="date" className={`form-input ${formErrors.due_date ? "input-error" : ""}`} value={form.due_date} onChange={(e) => setForm({ ...form, due_date: e.target.value })} />
                  {formErrors.due_date && <span className="form-error">{formErrors.due_date}</span>}
                </div>
                <div className="form-group">
                  <label className="form-label">Description</label>
                  <textarea className="form-input" rows={3} value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} placeholder="Optional notes or instructions..." />
                </div>
              </div>
            </div>
            <div className="modal-footer">
              <button className="btn btn-ghost" onClick={() => setShowModal(false)}>Cancel</button>
              <button className="btn btn-primary" onClick={handleCreate} disabled={modalLoading}>
                {modalLoading ? "Creating..." : "Create Event"}
              </button>
            </div>
          </div>
        </div>
      )}

      <ConfirmModal
        open={!!confirmDelete}
        title="Delete Event"
        description={confirmDelete ? `Delete "${confirmDelete.title}"? This cannot be undone.` : ""}
        confirmLabel="Delete"
        confirmVariant="destructive"
        onConfirm={handleDelete}
        onCancel={() => setConfirmDelete(null)}
      />
    </PageShell>
  );
}

// Use: Institution Admin — Risk Scorecard dashboard. KPIs, framework readiness bars, dept heatmap, AI risk panel, calendar preview, recent activity.

import { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import { api } from "../../lib/api";
import { PageShell } from "../../components/shared/PageShell";
import { useAuthStore } from "../../store/authStore";
import { BarChart3, AlertTriangle, Shield, Siren, Sparkles, RefreshCw, ChevronRight } from "lucide-react";
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer } from "recharts";

interface DashboardStats {
  overall_compliance: number;
  compliance_delta: number;
  active_gaps: number;
  critical_gaps: number;
  high_gaps: number;
  overdue_controls: number;
  open_incidents: number;
  critical_incidents: number;
}

interface FrameworkReadiness {
  framework_name: string;
  percentage: number;
  trend: "up" | "down" | "flat";
}

interface DeptScore {
  department_name: string;
  compliance_score: number;
}

interface CalendarEvent {
  calendar_id: string;
  event_type: string;
  title: string;
  due_date: string;
  is_completed: boolean;
}

interface AuditLog {
  audit_log_id: string;
  user_name: string;
  action_type: string;
  created_at: string;
}

interface AIRisk {
  rank: number;
  framework: string;
  description: string;
  severity: "critical" | "high" | "medium";
  affected_dept: string;
}

const EVENT_COLORS: Record<string, string> = {
  control_due: "var(--primary)",
  assessment_scheduled: "#8b5cf6",
  evidence_expiry: "var(--warning)",
  policy_review: "#6366f1",
  vendor_contract_expiry: "#f97316",
  audit_scheduled: "var(--success)",
};

function TrendArrow({ trend }: { trend: "up" | "down" | "flat" }) {
  if (trend === "up") return <span style={{ color: "var(--success)", fontSize: 14 }}>↑</span>;
  if (trend === "down") return <span style={{ color: "var(--danger)", fontSize: 14 }}>↓</span>;
  return <span style={{ color: "var(--text-muted)", fontSize: 14 }}>→</span>;
}

function ProgressBar({ pct }: { pct: number }) {
  const color = pct > 75 ? "var(--success)" : pct >= 50 ? "var(--warning)" : "var(--danger)";
  return (
    <div style={{ flex: 1, height: 8, background: "var(--surface-raised)", borderRadius: 4, overflow: "hidden" }}>
      <div style={{ width: `${pct}%`, height: "100%", background: color, borderRadius: 4, transition: "width 0.4s ease" }} />
    </div>
  );
}

function DeptHeatCard({ dept }: { dept: DeptScore }) {
  const s = dept.compliance_score;
  let bg = "#bbf7d0", text = "#15803d"; // green
  if (s < 75 && s >= 50) { bg = "#fef3c7"; text = "#d97706"; }
  if (s < 50) { bg = "#fee2e2"; text = "#dc2626"; }
  return (
    <div style={{ background: bg, borderRadius: 10, padding: "14px 16px", cursor: "pointer" }}
      onClick={() => {}}>
      <div style={{ fontWeight: 600, fontSize: 13, color: text }}>{dept.department_name}</div>
      <div style={{ fontSize: 22, fontWeight: 700, color: text, marginTop: 4 }}>{s}%</div>
    </div>
  );
}

export default function AdminDashboard() {
  const { user } = useAuthStore();
  const [stats, setStats] = useState<DashboardStats | null>(null);
  const [frameworks, setFrameworks] = useState<FrameworkReadiness[]>([]);
  const [departments, setDepartments] = useState<DeptScore[]>([]);
  const [calendarEvents, setCalendarEvents] = useState<CalendarEvent[]>([]);
  const [recentActivity, setRecentActivity] = useState<AuditLog[]>([]);
  const [loading, setLoading] = useState(true);
  const [aiRisks, setAiRisks] = useState<AIRisk[] | null>(null);
  const [aiLoading, setAiLoading] = useState(false);
  const [aiGenTime, setAiGenTime] = useState<string | null>(null);

  async function loadDashboardData() {
    setLoading(true);
    const [dashboardRes, calRes, auditRes] = await Promise.allSettled([
      api.get("/api/v1/institutions/dashboard"),
      api.get("/api/v1/calendar"),
      api.get("/api/v1/audit/recent?limit=10"),
    ]);

    if (dashboardRes.status === "fulfilled") {
      const payload = dashboardRes.value.data;
      setStats(payload.stats);
      setFrameworks(payload.frameworks ?? []);
      setDepartments(payload.departments ?? []);
      setAiRisks(payload.ai_risks ?? []);
      setAiGenTime("Just now");
    }

    if (calRes.status === "fulfilled") setCalendarEvents(calRes.value.data.slice(0, 7));
    if (auditRes.status === "fulfilled") setRecentActivity(auditRes.value.data);
    setLoading(false);
  }

  useEffect(() => {
    void loadDashboardData();
  }, []);

  async function handleGenerateRiskHeatmap() {
    setAiLoading(true);
    try {
      const res = await api.post("/api/v1/ai/admin/risk-heatmap", {});
      // The AI endpoint returns { ai_risks: [...], raw_response: {...} }
      const risks = res.data?.ai_risks ?? [];
      if (Array.isArray(risks) && risks.length > 0) {
        setAiRisks(risks as AIRisk[]);
        setAiGenTime(new Date().toLocaleTimeString());
      } else {
        // Fallback: re-fetch dashboard static risks
        const dashRes = await api.get("/api/v1/institutions/dashboard");
        setAiRisks(dashRes.data.ai_risks ?? []);
        setAiGenTime("Just now");
      }
    } catch {
      // Keep existing list if refresh fails; surface nothing to user
    }
    setAiLoading(false);
  }

  const ACTION_LABELS: Record<string, string> = {
    login: "Logged in", user_created: "Created user", reviewer_assigned: "Assigned reviewer",
    evidence_approved: "Approved evidence", role_changed: "Changed role",
  };

  return (
    <PageShell
      title={`Risk Overview`}
      subtitle={`Welcome back, ${user?.email?.split("@")[0] ?? "Admin"} — Last updated just now`}
    >
      {/* KPI Cards */}
      <div className="stats-grid" style={{ gridTemplateColumns: "repeat(4, 1fr)", marginBottom: 24 }}>
        {loading ? Array.from({ length: 4 }).map((_, i) => <div key={i} className="stat-card"><div className="skeleton" style={{ height: 60 }} /></div>) : (
          <>
            <div className="stat-card">
              <div className="stat-card-icon" style={{ background: "var(--primary-bg)", color: "var(--primary)" }}><BarChart3 size={20} /></div>
              <div className="stat-card-value">{stats?.overall_compliance}%</div>
              <div className="stat-card-label">Overall Compliance</div>
              <div style={{ fontSize: 12, marginTop: 4, color: (stats?.compliance_delta ?? 0) >= 0 ? "var(--success)" : "var(--danger)" }}>
                {(stats?.compliance_delta ?? 0) >= 0 ? "↑" : "↓"} {Math.abs(stats?.compliance_delta ?? 0)}% vs last month
              </div>
            </div>
            <div className="stat-card">
              <div className="stat-card-icon" style={{ background: "var(--warning-bg)", color: "var(--warning)" }}><AlertTriangle size={20} /></div>
              <div className="stat-card-value">{stats?.active_gaps}</div>
              <div className="stat-card-label">Active Gaps</div>
              <div style={{ fontSize: 11, marginTop: 4, color: "var(--text-muted)" }}>
                Critical: {stats?.critical_gaps} · High: {stats?.high_gaps}
              </div>
            </div>
            <div className="stat-card">
              <div className="stat-card-icon" style={{ background: "var(--danger-bg)", color: "var(--danger)" }}><Shield size={20} /></div>
              <div className="stat-card-value" style={{ color: (stats?.overdue_controls ?? 0) > 0 ? "var(--danger)" : undefined }}>{stats?.overdue_controls}</div>
              <div className="stat-card-label">Overdue Controls</div>
              <Link to="/compliance/controls?status=overdue" style={{ fontSize: 11, color: "var(--primary)", marginTop: 4, display: "block" }}>View controls →</Link>
            </div>
            <div className="stat-card">
              <div className="stat-card-icon" style={{ background: "#fee2e2", color: "var(--danger)" }}><Siren size={20} /></div>
              <div className="stat-card-value" style={{ color: (stats?.critical_incidents ?? 0) > 0 ? "var(--danger)" : undefined }}>{stats?.open_incidents}</div>
              <div className="stat-card-label">Open Incidents</div>
              <div style={{ fontSize: 11, marginTop: 4, color: "var(--text-muted)" }}>Critical: {stats?.critical_incidents}</div>
            </div>
          </>
        )}
      </div>

      {/* Framework Bars + Dept Heatmap */}
      <div className="grid-2" style={{ gap: 20, marginBottom: 24 }}>
        <div className="card">
          <div className="card-header"><h2 className="card-title">Framework Compliance</h2></div>
          <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
            {frameworks.map((fw) => (
              <div key={fw.framework_name}>
