              <Sparkles size={10} /> AI Insights
            </span>
          </div>
          {aiGenTime && <span style={{ fontSize: 11, color: "var(--text-muted)" }}>Generated: {aiGenTime}</span>}
        </div>
        {aiRisks === null ? (
