              <div key={ev.calendar_id} style={{ display: "flex", alignItems: "center", gap: 10, padding: "8px 0", borderBottom: "1px solid var(--border)" }}>
                <div style={{ width: 8, height: 8, borderRadius: "50%", background: EVENT_COLORS[ev.event_type] ?? "var(--text-muted)", flexShrink: 0 }} />
                <div style={{ flex: 1 }}>
                  <div style={{ fontSize: 13, fontWeight: 500 }}>{ev.title}</div>
                  <div style={{ fontSize: 11, color: "var(--text-muted)" }}>{new Date(ev.due_date).toLocaleDateString("en-IN", { day: "numeric", month: "short", year: "numeric" })}</div>
                </div>
                <span className="badge badge-draft" style={{ fontSize: 10 }}>{ev.event_type.replace(/_/g, " ")}</span>
              </div>
            ))}
          </div>
        </div>

        {/* Recent Activity */}
        <div className="card">
          <div className="card-header"><h2 className="card-title">Recent Activity</h2></div>
          <div>
            {recentActivity.length === 0 ? (
              <p style={{ color: "var(--text-muted)", fontSize: 13 }}>No recent activity.</p>
            ) : recentActivity.slice(0, 10).map((log) => (
              <div key={log.audit_log_id} style={{ display: "flex", alignItems: "center", gap: 10, padding: "8px 0", borderBottom: "1px solid var(--border)" }}>
                <div style={{ flex: 1 }}>
                  <span style={{ fontSize: 13, fontWeight: 500 }}>{log.user_name ?? "System"}</span>
                  <span style={{ fontSize: 12, color: "var(--text-muted)", marginLeft: 8 }}>{ACTION_LABELS[log.action_type] ?? log.action_type}</span>
                </div>
                <span style={{ fontSize: 11, color: "var(--text-muted)", fontFamily: "var(--font-mono)" }}>
                  {new Date(log.created_at).toLocaleTimeString("en-IN", { hour: "2-digit", minute: "2-digit" })}
                </span>
              </div>
            ))}
          </div>
        </div>
      </div>
    </PageShell>
  );
}

// Use: Institution Admin — Department Manager. List, create, edit, assign reviewer, and toggle status.

import { useState, useEffect, useCallback } from "react";
import { api } from "../../lib/api";
import { PageShell } from "../../components/shared/PageShell";
import { ConfirmModal } from "../../components/shared/ConfirmModal";
import { useToast } from "../../components/shared/Toast";
import { Plus, Edit, UserCheck, Building2 } from "lucide-react";

interface Department {
  department_id: string;
  department_name: string;
  department_code: string | null;
  hod_name: string | null;
  reviewer_user_id: string | null;
  reviewer_name: string | null;
  reviewer_email: string | null;
  is_active: boolean;
}

interface ReviewerUser {
  user_id: string;
  full_name: string;
  email: string;
}

interface DeptForm {
  department_name: string;
  department_code: string;
  hod_name: string;
}

const EMPTY_DEPT_FORM: DeptForm = { department_name: "", department_code: "", hod_name: "" };

export default function Departments() {
  const toast = useToast();
  const [departments, setDepartments] = useState<Department[]>([]);
  const [reviewerUsers, setReviewerUsers] = useState<ReviewerUser[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("All");

  // Modals
  const [deptModal, setDeptModal] = useState<{ open: boolean; editTarget: Department | null }>({ open: false, editTarget: null });
  const [reviewerModal, setReviewerModal] = useState<{ open: boolean; dept: Department | null }>({ open: false, dept: null });
  const [confirmToggle, setConfirmToggle] = useState<Department | null>(null);
  const [form, setForm] = useState<DeptForm>(EMPTY_DEPT_FORM);
  const [selectedReviewer, setSelectedReviewer] = useState("");
  const [formErrors, setFormErrors] = useState<Partial<DeptForm>>({});
  const [modalLoading, setModalLoading] = useState(false);

  const fetchDepartments = useCallback(async () => {
    setLoading(true);
    try {
      const params: Record<string, string> = {};
      if (statusFilter !== "All") params.status = statusFilter;
      if (search) params.search = search;
      const res = await api.get("/api/v1/departments", { params });
      setDepartments(res.data);
    } catch { toast.error("Failed to load departments"); }
    setLoading(false);
  }, [search, statusFilter]);

  useEffect(() => { fetchDepartments(); }, [fetchDepartments]);

  useEffect(() => {
    api.get("/api/v1/users", { params: { role: "Department Reviewer" } })
      .then((r) => setReviewerUsers(r.data))
      .catch(() => {});
  }, []);

  function openAddModal() {
    setForm(EMPTY_DEPT_FORM);
    setFormErrors({});
    setDeptModal({ open: true, editTarget: null });
  }

  function openEditModal(dept: Department) {
    setForm({ department_name: dept.department_name, department_code: dept.department_code ?? "", hod_name: dept.hod_name ?? "" });
    setFormErrors({});
    setDeptModal({ open: true, editTarget: dept });
  }

  function validateForm(): boolean {
    const errors: Partial<DeptForm> = {};
    if (!form.department_name.trim()) errors.department_name = "Department name is required";
    setFormErrors(errors);
    return Object.keys(errors).length === 0;
  }

  async function handleSave() {
    if (!validateForm()) return;
    setModalLoading(true);
    try {
      if (deptModal.editTarget) {
        await api.patch(`/api/v1/departments/${deptModal.editTarget.department_id}`, form);
        toast.success("Department updated");
      } else {
        await api.post("/api/v1/departments", form);
        toast.success("Department created");
      }
      setDeptModal({ open: false, editTarget: null });
      fetchDepartments();
    } catch (err: any) {
      toast.error(err?.response?.data?.detail ?? "Operation failed");
    }
    setModalLoading(false);
  }

  async function handleAssignReviewer() {
    if (!reviewerModal.dept || !selectedReviewer) return;
    setModalLoading(true);
    try {
      await api.patch(`/api/v1/departments/${reviewerModal.dept.department_id}`, { reviewer_user_id: selectedReviewer });
      toast.success("Reviewer assigned successfully");
      setReviewerModal({ open: false, dept: null });
      setSelectedReviewer("");
      fetchDepartments();
    } catch (err: any) {
      toast.error(err?.response?.data?.detail ?? "Failed to assign reviewer");
    }
    setModalLoading(false);
  }

  async function handleToggleStatus() {
    if (!confirmToggle) return;
    try {
      await api.put(`/api/v1/departments/${confirmToggle.department_id}/status`, { is_active: !confirmToggle.is_active });
      toast.success(`Department ${confirmToggle.is_active ? "deactivated" : "activated"}`);
      setConfirmToggle(null);
      fetchDepartments();
    } catch { toast.error("Failed to update status"); }
  }

  return (
    <PageShell
      title="Departments"
      subtitle="Manage academic and administrative departments"
      actions={
        <button className="btn btn-primary" onClick={openAddModal} style={{ display: "flex", alignItems: "center", gap: 6 }}>
          <Plus size={15} /> Add Department
        </button>
      }
    >
      {/* Filter Row */}
      <div style={{ display: "flex", gap: 10, marginBottom: 20 }}>
        <input className="form-input" placeholder="Search by name or code..." value={search} onChange={(e) => setSearch(e.target.value)} style={{ flex: 1, fontSize: 13 }} />
        <select className="form-input" value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)} style={{ minWidth: 130, fontSize: 13 }}>
          <option value="All">All Status</option>
          <option value="Active">Active</option>
          <option value="Inactive">Inactive</option>
        </select>
      </div>

      {/* Table */}
      <div className="card">
        <div className="table-wrapper">
          <table className="data-table">
            <thead>
              <tr><th>Department Name</th><th>Code</th><th>HOD Name</th><th>Assigned Reviewer</th><th>Status</th><th>Actions</th></tr>
            </thead>
            <tbody>
              {loading ? (
                Array.from({ length: 5 }).map((_, i) => (
                  <tr key={i}>{Array.from({ length: 6 }).map((_, j) => <td key={j}><div className="skeleton" style={{ height: 18, borderRadius: 4 }} /></td>)}</tr>
                ))
              ) : departments.length === 0 ? (
                <tr>
                  <td colSpan={6} style={{ textAlign: "center", padding: "48px 16px" }}>
                    <Building2 size={36} style={{ color: "var(--text-muted)", display: "block", margin: "0 auto 10px" }} />
                    <p style={{ color: "var(--text-muted)", margin: 0, fontSize: 14 }}>No departments created yet.</p>
                    <button className="btn btn-primary" onClick={openAddModal} style={{ marginTop: 12, display: "inline-flex", alignItems: "center", gap: 6 }}>
                      <Plus size={14} /> Add Department
                    </button>
                  </td>
                </tr>
              ) : departments.map((dept) => (
                <tr key={dept.department_id}>
                  <td style={{ fontWeight: 500 }}>{dept.department_name}</td>
                  <td><code style={{ fontSize: 12, color: "var(--text-muted)" }}>{dept.department_code ?? "—"}</code></td>
                  <td>{dept.hod_name ?? "—"}</td>
                  <td>
                    {dept.reviewer_name ? (
                      <div>
                        <div style={{ fontSize: 13, fontWeight: 500 }}>{dept.reviewer_name}</div>
                        <div style={{ fontSize: 11, color: "var(--text-muted)" }}>{dept.reviewer_email}</div>
                      </div>
                    ) : (
                      <span style={{ color: "var(--warning)", fontSize: 13, fontStyle: "italic" }}>Unassigned</span>
                    )}
                  </td>
                  <td><span className={`badge ${dept.is_active ? "badge-compliant" : "badge-inactive"}`}>{dept.is_active ? "Active" : "Inactive"}</span></td>
                  <td>
                    <div style={{ display: "flex", gap: 6 }}>
                      <button className="btn btn-ghost" onClick={() => openEditModal(dept)} style={{ padding: "4px 10px", fontSize: 12, display: "flex", alignItems: "center", gap: 4 }}>
                        <Edit size={12} /> Edit
                      </button>
                      <button className="btn btn-ghost" onClick={() => { setReviewerModal({ open: true, dept }); setSelectedReviewer(dept.reviewer_user_id ?? ""); }} style={{ padding: "4px 10px", fontSize: 12, display: "flex", alignItems: "center", gap: 4 }}>
                        <UserCheck size={12} /> {dept.reviewer_user_id ? "Change" : "Assign"} Reviewer
                      </button>
                      <button className="btn btn-ghost" onClick={() => setConfirmToggle(dept)} style={{ padding: "4px 10px", fontSize: 12, color: dept.is_active ? "var(--danger)" : "var(--success)" }}>
                        {dept.is_active ? "Deactivate" : "Activate"}
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Add/Edit Department Modal */}
      {deptModal.open && (
        <div className="modal-overlay" onClick={() => setDeptModal({ open: false, editTarget: null })}>
          <div className="modal" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h2 className="modal-title">{deptModal.editTarget ? "Edit Department" : "Add Department"}</h2>
              <button className="modal-close" onClick={() => setDeptModal({ open: false, editTarget: null })}>×</button>
            </div>
            <div className="modal-body">
              <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
                <div className="form-group">
                  <label className="form-label">Department Name *</label>
                  <input className={`form-input ${formErrors.department_name ? "input-error" : ""}`} value={form.department_name} onChange={(e) => setForm({ ...form, department_name: e.target.value })} placeholder="e.g. Computer Science" />
                  {formErrors.department_name && <span className="form-error">{formErrors.department_name}</span>}
                </div>
                <div className="form-group">
                  <label className="form-label">Department Code</label>
                  <input className="form-input" value={form.department_code} onChange={(e) => setForm({ ...form, department_code: e.target.value })} placeholder="e.g. CS, ADMIN, FIN" />
                </div>
                <div className="form-group">
                  <label className="form-label">Head of Department (HOD)</label>
                  <input className="form-input" value={form.hod_name} onChange={(e) => setForm({ ...form, hod_name: e.target.value })} placeholder="e.g. Prof. Ramesh Kumar" />
                </div>
              </div>
            </div>
            <div className="modal-footer">
              <button className="btn btn-ghost" onClick={() => setDeptModal({ open: false, editTarget: null })}>Cancel</button>
              <button className="btn btn-primary" onClick={handleSave} disabled={modalLoading}>
                {modalLoading ? "Saving..." : deptModal.editTarget ? "Save Changes" : "Create Department"}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Assign Reviewer Modal */}
      {reviewerModal.open && reviewerModal.dept && (
        <div className="modal-overlay" onClick={() => setReviewerModal({ open: false, dept: null })}>
          <div className="modal" style={{ maxWidth: 440 }} onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h2 className="modal-title">Assign Department Reviewer</h2>
              <button className="modal-close" onClick={() => setReviewerModal({ open: false, dept: null })}>×</button>
            </div>
            <div className="modal-body">
              <p style={{ fontSize: 13, color: "var(--text-secondary)", marginBottom: 16 }}>
                Select a user with <strong>Department Reviewer</strong> role to assign to <strong>{reviewerModal.dept.department_name}</strong>
              </p>
              <div className="form-group">
                <label className="form-label">Reviewer</label>
                <select className="form-input" value={selectedReviewer} onChange={(e) => setSelectedReviewer(e.target.value)}>
                  <option value="">Select reviewer...</option>
                  {reviewerUsers.map((u) => (
                    <option key={u.user_id} value={u.user_id}>{u.full_name} — {u.email}</option>
                  ))}
                </select>
                {reviewerUsers.length === 0 && (
                  <p style={{ fontSize: 12, color: "var(--warning)", marginTop: 6 }}>No Department Reviewer users found. Create one first in User Management.</p>
                )}
              </div>
            </div>
            <div className="modal-footer">
              <button className="btn btn-ghost" onClick={() => setReviewerModal({ open: false, dept: null })}>Cancel</button>
              <button className="btn btn-primary" onClick={handleAssignReviewer} disabled={!selectedReviewer || modalLoading}>
                {modalLoading ? "Assigning..." : "Assign"}
              </button>
            </div>
          </div>
        </div>
      )}

      <ConfirmModal
        open={!!confirmToggle}
        title={confirmToggle?.is_active ? "Deactivate Department" : "Activate Department"}
        description={confirmToggle ? `Are you sure you want to ${confirmToggle.is_active ? "deactivate" : "activate"} "${confirmToggle.department_name}"?` : ""}
        confirmLabel={confirmToggle?.is_active ? "Deactivate" : "Activate"}
        confirmVariant={confirmToggle?.is_active ? "destructive" : "default"}
        onConfirm={handleToggleStatus}
        onCancel={() => setConfirmToggle(null)}
      />
    </PageShell>
  );
}

// Use: Generates PDF executive briefing reports using AI summaries.

import { useState, useEffect } from "react";
import { api } from "../../lib/api";
import { PageShell } from "../../components/shared/PageShell";
import { useToast } from "../../components/shared/Toast";
import { FileText, Plus, Sparkles, Download, Calendar } from "lucide-react";

interface AuditReport {
  report_id: string;
  report_name: string;
  report_type: string;
  file_path: string;
  generated_at: string;
}

const REPORT_TYPE_LABELS: Record<string, string> = {
  naac: "NAAC Criteria 4 & 6 Verification Briefing",
  iso_readiness: "ISO 27001 Gap Analysis Executive Report",
  dpdp_assessment: "DPDP Section 8 Compliance Assessment",
  custom: "Compliance Status Custom Executive Briefing",
};

export default function Reports() {
  const toast = useToast();
  const [reports, setReports] = useState<AuditReport[]>([]);
  const [loading, setLoading] = useState(true);
  const [modalOpen, setModalOpen] = useState(false);
  const [modalLoading, setModalLoading] = useState(false);
  const [reportType, setReportType] = useState("iso_readiness");
  const [periodFrom, setPeriodFrom] = useState("");
  const [periodTo, setPeriodTo] = useState("");

  async function fetchReports() {
    setLoading(true);
    try {
      const res = await api.get("/api/v1/policies/reports");
      setReports(res.data);
    } catch {
      toast.error("Failed to load reports");
    }
    setLoading(false);
  }

  useEffect(() => {
    fetchReports();
  }, []);

  async function handleGenerate() {
    setModalLoading(true);
    try {
      await api.post("/api/v1/policies/reports/generate", {
        report_type: reportType,
        period_from: periodFrom || null,
        period_to: periodTo || null,
      });
      toast.success("Report generated successfully");
      setModalOpen(false);
      fetchReports();
    } catch (err: any) {
      toast.error(err?.response?.data?.detail ?? "Failed to generate report");
    }
    setModalLoading(false);
  }

  return (
    <PageShell
      title="Executive Briefings"
      subtitle="Generate and review compliance executive briefing reports"
      actions={
        <button
          className="btn btn-primary"
          onClick={() => setModalOpen(true)}
          style={{ display: "flex", alignItems: "center", gap: 6 }}
        >
          <Plus size={16} /> New Briefing
        </button>
      }
    >
      <div className="card">
        <div className="card-header">
          <h2 className="card-title">Generated Briefings</h2>
        </div>
        <div className="table-wrapper">
          <table className="data-table">
            <thead>
              <tr>
                <th>Report Name</th>
                <th>Type</th>
                <th>Generated</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {loading ? (
                Array.from({ length: 3 }).map((_, i) => (
                  <tr key={i}>
                    {Array.from({ length: 4 }).map((_, j) => (
                      <td key={j}>
                        <div className="skeleton" style={{ height: 18, borderRadius: 4 }} />
                      </td>
                    ))}
                  </tr>
                ))
              ) : reports.length === 0 ? (
                <tr>
                  <td colSpan={4} style={{ textAlign: "center", padding: "48px 16px" }}>
                    <FileText
                      size={36}
                      style={{
                        color: "var(--text-muted)",
                        marginBottom: 10,
                        display: "block",
                        margin: "0 auto 10px",
                      }}
                    />
                    <p style={{ color: "var(--text-muted)", margin: 0, fontSize: 14 }}>
                      No reports generated yet.
                    </p>
                  </td>
                </tr>
              ) : (
                reports.map((report) => (
                  <tr key={report.report_id}>
                    <td style={{ fontWeight: 600 }}>{report.report_name}</td>
                    <td>
                      <span className="badge badge-draft">
                        {REPORT_TYPE_LABELS[report.report_type] ?? report.report_type}
                      </span>
                    </td>
                    <td
                      style={{
                        fontSize: 12,
                        color: "var(--text-muted)",
                        fontFamily: "var(--font-mono)",
                      }}
                    >
                      {new Date(report.generated_at).toLocaleString("en-IN")}
                    </td>
                    <td>
                      <a
                        href={`${import.meta.env.VITE_API_URL ?? "http://localhost:8000"}${
                          report.file_path
                        }`}
                        download
                        className="btn btn-ghost"
                        style={{
                          padding: "4px 10px",
                          fontSize: 12,
                          display: "inline-flex",
                          alignItems: "center",
                          gap: 4,
                        }}
                      >
                        <Download size={13} /> Download PDF
                      </a>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {modalOpen && (
        <div className="modal-overlay" onClick={() => setModalOpen(false)}>
          <div className="modal" style={{ maxWidth: 500 }} onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h2 className="modal-title" style={{ display: "flex", alignItems: "center", gap: 8 }}>
                <Sparkles size={18} style={{ color: "var(--primary)" }} /> Generate Executive Briefing
              </h2>
              <button className="modal-close" onClick={() => setModalOpen(false)}>
                ×
              </button>
            </div>
            <div className="modal-body">
              <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
                <div className="form-group">
                  <label className="form-label">Report Type *</label>
                  <select
                    className="form-input"
                    value={reportType}
                    onChange={(e) => setReportType(e.target.value)}
                  >
                    {Object.entries(REPORT_TYPE_LABELS).map(([k, v]) => (
                      <option key={k} value={k}>
                        {v}
                      </option>
                    ))}
                  </select>
                </div>
                <div className="grid-2" style={{ gap: 16 }}>
                  <div className="form-group">
                    <label className="form-label">Period From</label>
                    <div style={{ position: "relative" }}>
                      <Calendar
                        size={14}
                        style={{
                          position: "absolute",
                          left: 10,
                          top: "50%",
                          transform: "translateY(-50%)",
                          color: "var(--text-muted)",
                        }}
                      />
                      <input
                        type="date"
                        className="form-input"
                        value={periodFrom}
                        onChange={(e) => setPeriodFrom(e.target.value)}
                        style={{ paddingLeft: 30 }}
                      />
                    </div>
                  </div>
                  <div className="form-group">
                    <label className="form-label">Period To</label>
                    <div style={{ position: "relative" }}>
                      <Calendar
                        size={14}
                        style={{
                          position: "absolute",
                          left: 10,
                          top: "50%",
                          transform: "translateY(-50%)",
                          color: "var(--text-muted)",
                        }}
                      />
                      <input
                        type="date"
                        className="form-input"
                        value={periodTo}
                        onChange={(e) => setPeriodTo(e.target.value)}
                        style={{ paddingLeft: 30 }}
                      />
                    </div>
                  </div>
                </div>
                <p style={{ fontSize: 12, color: "var(--text-muted)", margin: 0 }}>
                  Generating this briefing will compile compliance readiness data and trigger AI model summaries.
                </p>
              </div>
            </div>
            <div className="modal-footer">
              <button className="btn btn-ghost" onClick={() => setModalOpen(false)}>
                Cancel
              </button>
              <button
                className="btn btn-primary"
                onClick={handleGenerate}
                disabled={modalLoading}
                style={{ display: "flex", alignItems: "center", gap: 6 }}
              >
                {modalLoading ? (
                  <>
                    <div className="spinner" style={{ width: 14, height: 14, borderWidth: 2 }} />
                    Generating...
                  </>
                ) : (
                  <>
                    <Sparkles size={14} /> Generate
                  </>
                )}
              </button>
            </div>
          </div>
        </div>
      )}
    </PageShell>
  );
}

// Use: Institution Admin — User Management. List, invite, deactivate, unlock, and change role for institution users.

import { useState, useEffect, useCallback } from "react";
import { api } from "../../lib/api";
import { PageShell } from "../../components/shared/PageShell";
import { ConfirmModal } from "../../components/shared/ConfirmModal";
import { useToast } from "../../components/shared/Toast";
import { UserPlus, Lock, Unlock, AlertCircle } from "lucide-react";

interface User {
  user_id: string;
  full_name: string;
  email: string;
  role_name: string;
  is_active: boolean;
  is_locked: boolean;
  last_login: string | null;
  created_at: string;
  department_name: string | null;
}

interface InviteForm {
  full_name: string;
  email: string;
  role_name: string;
  department_id?: string;
}

interface Department {
  department_id: string;
  department_name: string;
}

const ASSIGNABLE_ROLES = [
  "Institution Admin", "Compliance Officer", "IT Security Officer",
  "Auditor", "Department Reviewer", "Vendor Reviewer", "Policy Approver", "Read-Only Assessor",
];

const EMPTY_INVITE: InviteForm = { full_name: "", email: "", role_name: "Department Reviewer" };

export default function Users() {
  const toast = useToast();
  const [users, setUsers] = useState<User[]>([]);
  const [departments, setDepartments] = useState<Department[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [roleFilter, setRoleFilter] = useState("All");
  const [statusFilter, setStatusFilter] = useState("All");

  // Modals
  const [inviteModal, setInviteModal] = useState(false);
  const [roleModal, setRoleModal] = useState<{ open: boolean; user: User | null }>({ open: false, user: null });
  const [newRole, setNewRole] = useState("");
  const [confirmAction, setConfirmAction] = useState<{ user: User; action: "deactivate" | "activate" | "unlock" } | null>(null);
  const [form, setForm] = useState<InviteForm>(EMPTY_INVITE);
  const [formErrors, setFormErrors] = useState<Partial<InviteForm>>({});
  const [modalLoading, setModalLoading] = useState(false);

  const fetchUsers = useCallback(async () => {
    setLoading(true);
    const params: Record<string, string> = {};
    if (search) params.search = search;
    if (roleFilter !== "All") params.role = roleFilter;
    if (statusFilter !== "All") params.status = statusFilter;
    try {
      const res = await api.get("/api/v1/users", { params });
      setUsers(res.data);
    } catch { toast.error("Failed to load users"); }
    setLoading(false);
  }, [search, roleFilter, statusFilter]);

  useEffect(() => { fetchUsers(); }, [fetchUsers]);
  useEffect(() => {
    api.get("/api/v1/departments").then((r) => setDepartments(r.data)).catch(() => {});
  }, []);

  function validateInvite(): boolean {
    const errors: Partial<InviteForm> = {};
    if (!form.full_name.trim()) errors.full_name = "Name is required";
    if (!form.email.trim()) errors.email = "Email is required";
    else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email)) errors.email = "Invalid email format";
    if (!form.role_name) errors.role_name = "Role is required";
    setFormErrors(errors);
    return Object.keys(errors).length === 0;
  }

  async function handleInvite() {
    if (!validateInvite()) return;
    setModalLoading(true);
    try {
      await api.post("/api/v1/users/invite", form);
      toast.success("User invited — they will receive an email with login instructions");
      setInviteModal(false);
      setForm(EMPTY_INVITE);
      fetchUsers();
    } catch (err: any) {
      toast.error(err?.response?.data?.detail ?? "Invite failed");
    }
    setModalLoading(false);
  }

  async function handleChangeRole() {
    if (!roleModal.user || !newRole) return;
    setModalLoading(true);
    try {
      await api.patch(`/api/v1/users/${roleModal.user.user_id}/role`, { role_name: newRole });
      toast.success("Role updated successfully");
      setRoleModal({ open: false, user: null });
      setNewRole("");
      fetchUsers();
    } catch (err: any) {
      toast.error(err?.response?.data?.detail ?? "Failed to change role");
    }
    setModalLoading(false);
  }

  async function handleConfirmAction() {
    if (!confirmAction) return;
    const { user, action } = confirmAction;
    try {
      if (action === "unlock") {
        await api.post(`/api/v1/users/${user.user_id}/unlock`);
        toast.success("Account unlocked");
      } else {
        await api.put(`/api/v1/users/${user.user_id}/status`, { is_active: action === "activate" });
        toast.success(`User ${action}d`);
      }
      setConfirmAction(null);
      fetchUsers();
    } catch { toast.error("Action failed"); }
  }

  return (
    <PageShell
      title="User Management"
      subtitle="Manage institution users, roles, and access"
      actions={
        <button className="btn btn-primary" onClick={() => { setForm(EMPTY_INVITE); setFormErrors({}); setInviteModal(true); }} style={{ display: "flex", alignItems: "center", gap: 6 }}>
          <UserPlus size={15} /> Invite User
        </button>
      }
    >
      {/* Filters */}
      <div style={{ display: "flex", gap: 10, marginBottom: 20, flexWrap: "wrap" }}>
        <input className="form-input" placeholder="Search by name or email..." value={search} onChange={(e) => setSearch(e.target.value)} style={{ flex: 1, minWidth: 200, fontSize: 13 }} />
        <select className="form-input" value={roleFilter} onChange={(e) => setRoleFilter(e.target.value)} style={{ minWidth: 160, fontSize: 13 }}>
          <option value="All">All Roles</option>
          {ASSIGNABLE_ROLES.map((r) => <option key={r}>{r}</option>)}
        </select>
        <select className="form-input" value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)} style={{ minWidth: 130, fontSize: 13 }}>
          <option value="All">All Status</option>
          <option value="Active">Active</option>
          <option value="Inactive">Inactive</option>
          <option value="Locked">Locked</option>
        </select>
      </div>

      {/* Table */}
      <div className="card">
        <div className="table-wrapper">
          <table className="data-table">
            <thead>
              <tr><th>Name</th><th>Email</th><th>Role</th><th>Department</th><th>Status</th><th>Last Login</th><th>Actions</th></tr>
            </thead>
            <tbody>
              {loading ? (
                Array.from({ length: 6 }).map((_, i) => (
                  <tr key={i}>{Array.from({ length: 7 }).map((_, j) => <td key={j}><div className="skeleton" style={{ height: 18, borderRadius: 4 }} /></td>)}</tr>
                ))
              ) : users.length === 0 ? (
                <tr><td colSpan={7} style={{ textAlign: "center", color: "var(--text-muted)", padding: 40 }}>No users found.</td></tr>
              ) : users.map((u) => (
                <tr key={u.user_id}>
                  <td>
                    <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                      <div style={{ width: 32, height: 32, borderRadius: "50%", background: "var(--primary-bg)", color: "var(--primary)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 13, fontWeight: 700, flexShrink: 0 }}>
                        {u.full_name.charAt(0).toUpperCase()}
                      </div>
                      <span style={{ fontWeight: 500 }}>{u.full_name}</span>
                    </div>
                  </td>
                  <td style={{ fontSize: 13, color: "var(--text-secondary)" }}>{u.email}</td>
                  <td><span className="badge badge-draft">{u.role_name}</span></td>
                  <td style={{ fontSize: 13, color: "var(--text-muted)" }}>{u.department_name ?? "—"}</td>
                  <td>
                    {u.is_locked ? (
                      <span className="badge badge-non_compliant" style={{ display: "flex", alignItems: "center", gap: 4 }}>
                        <Lock size={10} /> Locked
                      </span>
                    ) : (
                      <span className={`badge ${u.is_active ? "badge-compliant" : "badge-inactive"}`}>
                        {u.is_active ? "Active" : "Inactive"}
                      </span>
                    )}
                  </td>
                  <td style={{ fontSize: 12, color: "var(--text-muted)" }}>{u.last_login ? new Date(u.last_login).toLocaleDateString("en-IN") : "Never"}</td>
                  <td>
                    <div style={{ display: "flex", gap: 4, flexWrap: "wrap" }}>
                      <button className="btn btn-ghost" onClick={() => { setRoleModal({ open: true, user: u }); setNewRole(u.role_name); }} style={{ padding: "4px 8px", fontSize: 11 }}>
                        Change Role
                      </button>
                      {u.is_locked && (
                        <button className="btn btn-ghost" onClick={() => setConfirmAction({ user: u, action: "unlock" })} style={{ padding: "4px 8px", fontSize: 11, display: "flex", alignItems: "center", gap: 4 }}>
                          <Unlock size={11} /> Unlock
                        </button>
                      )}
                      <button
                        className="btn btn-ghost"
                        onClick={() => setConfirmAction({ user: u, action: u.is_active ? "deactivate" : "activate" })}
                        style={{ padding: "4px 8px", fontSize: 11, color: u.is_active ? "var(--danger)" : "var(--success)" }}
                      >
                        {u.is_active ? "Deactivate" : "Activate"}
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Invite Modal */}
      {inviteModal && (
        <div className="modal-overlay" onClick={() => setInviteModal(false)}>
          <div className="modal" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h2 className="modal-title">Invite New User</h2>
              <button className="modal-close" onClick={() => setInviteModal(false)}>×</button>
            </div>
            <div className="modal-body">
              <div className="card" style={{ background: "var(--info-bg)", border: "1px solid var(--info)", padding: "12px 16px", borderRadius: 8, marginBottom: 16, display: "flex", alignItems: "flex-start", gap: 10 }}>
                <AlertCircle size={16} style={{ color: "var(--info)", flexShrink: 0, marginTop: 2 }} />
                <p style={{ margin: 0, fontSize: 13, color: "var(--text-secondary)" }}>
                  An email will be sent with a secure invitation link. The user will set their own password on first login.
                </p>
              </div>
              <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
                <div className="form-group">
                  <label className="form-label">Full Name *</label>
                  <input className={`form-input ${formErrors.full_name ? "input-error" : ""}`} value={form.full_name} onChange={(e) => setForm({ ...form, full_name: e.target.value })} placeholder="e.g. Priya Sharma" />
                  {formErrors.full_name && <span className="form-error">{formErrors.full_name}</span>}
                </div>
                <div className="form-group">
                  <label className="form-label">Email Address *</label>
                  <input type="email" className={`form-input ${formErrors.email ? "input-error" : ""}`} value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} placeholder="user@institution.ac.in" />
                  {formErrors.email && <span className="form-error">{formErrors.email}</span>}
                </div>
                <div className="form-group">
                  <label className="form-label">Role *</label>
                  <select className={`form-input ${formErrors.role_name ? "input-error" : ""}`} value={form.role_name} onChange={(e) => setForm({ ...form, role_name: e.target.value })}>
                    {ASSIGNABLE_ROLES.map((r) => <option key={r}>{r}</option>)}
                  </select>
                  {formErrors.role_name && <span className="form-error">{formErrors.role_name}</span>}
                </div>
                {form.role_name === "Department Reviewer" && (
                  <div className="form-group">
                    <label className="form-label">Assign to Department</label>
                    <select className="form-input" value={form.department_id ?? ""} onChange={(e) => setForm({ ...form, department_id: e.target.value || undefined })}>
                      <option value="">— Select department (optional) —</option>
                      {departments.map((d) => <option key={d.department_id} value={d.department_id}>{d.department_name}</option>)}
                    </select>
                  </div>
                )}
              </div>
            </div>
            <div className="modal-footer">
              <button className="btn btn-ghost" onClick={() => setInviteModal(false)}>Cancel</button>
              <button className="btn btn-primary" onClick={handleInvite} disabled={modalLoading}>
                {modalLoading ? "Sending..." : "Send Invitation"}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Change Role Modal */}
      {roleModal.open && roleModal.user && (
        <div className="modal-overlay" onClick={() => setRoleModal({ open: false, user: null })}>
          <div className="modal" style={{ maxWidth: 420 }} onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h2 className="modal-title">Change Role</h2>
              <button className="modal-close" onClick={() => setRoleModal({ open: false, user: null })}>×</button>
            </div>
            <div className="modal-body">
              <p style={{ fontSize: 13, color: "var(--text-secondary)", marginBottom: 16 }}>
                Changing the role of <strong>{roleModal.user.full_name}</strong> will affect their access immediately.
              </p>
              <div className="form-group">
                <label className="form-label">New Role</label>
                <select className="form-input" value={newRole} onChange={(e) => setNewRole(e.target.value)}>
                  {ASSIGNABLE_ROLES.map((r) => <option key={r}>{r}</option>)}
                </select>
              </div>
            </div>
            <div className="modal-footer">
              <button className="btn btn-ghost" onClick={() => setRoleModal({ open: false, user: null })}>Cancel</button>
              <button className="btn btn-primary" onClick={handleChangeRole} disabled={!newRole || newRole === roleModal.user.role_name || modalLoading}>
                {modalLoading ? "Updating..." : "Update Role"}
              </button>
            </div>
          </div>
        </div>
      )}

      <ConfirmModal
        open={!!confirmAction}
        title={
          confirmAction?.action === "unlock" ? "Unlock Account" :
          confirmAction?.action === "deactivate" ? "Deactivate User" : "Activate User"
        }
        description={
          confirmAction?.action === "unlock"
            ? `Unlock "${confirmAction.user.full_name}"'s account? They will be able to log in again.`
            : confirmAction?.action === "deactivate"
            ? `Deactivating "${confirmAction.user.full_name}" will prevent them from logging in immediately.`
            : confirmAction
            ? `Activating "${confirmAction.user.full_name}" will restore their login access.`
            : ""
        }
        confirmLabel={confirmAction?.action === "unlock" ? "Unlock" : confirmAction?.action === "deactivate" ? "Deactivate" : "Activate"}
        confirmVariant={confirmAction?.action === "deactivate" ? "destructive" : "default"}
        onConfirm={handleConfirmAction}
        onCancel={() => setConfirmAction(null)}
      />
    </PageShell>
  );
}

// Use: History page listing all organizational policies previously approved or rejected.

import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { api } from "../../lib/api";
import { PageShell } from "../../components/shared/PageShell";
import { FileText, CheckCircle, XCircle, Eye } from "lucide-react";

type Policy = {
  policy_id: string;
  policy_name: string;
  version_number: number;
  policy_status: string;
  related_control_id?: string | null;
  created_at: string;
};

export default function History() {
  const [policies, setPolicies] = useState<Policy[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function load() {
      try {
        const { data } = await api.get("/api/v1/policies");
        setPolicies(Array.isArray(data) ? data : []);
      } catch (err) {
        console.error("Failed to load policy history", err);
      } finally {
        setLoading(false);
      }
    }
    void load();
  }, []);

  const historyPolicies = policies.filter(
    (p) => p.policy_status === "approved" || p.policy_status === "rejected"
  );

  return (
    <div className="page-panel">
      <PageShell title="Policy Review History" context="Archived decisions and past review audits." />

      {loading ? (
        <p style={{ marginTop: 20 }}>Loading policy archive…</p>
      ) : (
        <div style={{ marginTop: 24, display: "flex", flexDirection: "column", gap: 16 }}>
          <div className="card" style={{ padding: 20 }}>
            <h3 style={{ marginTop: 0, marginBottom: 16 }}>Decision Archive</h3>

            {historyPolicies.length === 0 ? (
              <p style={{ color: "var(--muted)", margin: 0, fontSize: 13 }}>
                No completed reviews in history.
              </p>
            ) : (
              <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
                {historyPolicies.map((policy) => {
                  const isApproved = policy.policy_status === "approved";
                  return (
                    <div
                      key={policy.policy_id}
                      style={{
                        border: "1px solid var(--border)",
                        borderRadius: 10,
                        padding: 16,
                        display: "flex",
                        justifyContent: "space-between",
                        alignItems: "center",
                        background: "var(--surface)",
                      }}
                    >
                      <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                        <div
                          style={{
                            width: 36,
                            height: 36,
                            borderRadius: 8,
                            backgroundColor: isApproved ? "#E8F8F0" : "#FEECEB",
                            display: "flex",
                            alignItems: "center",
                            justifyContent: "center",
                            color: isApproved ? "#10B981" : "#EF4444",
                          }}
                        >
                          {isApproved ? <CheckCircle size={18} /> : <XCircle size={18} />}
                        </div>
                        <div>
                          <strong style={{ display: "block", fontSize: 14 }}>{policy.policy_name}</strong>
                          <span style={{ fontSize: 12, color: "var(--muted)" }}>
                            v{policy.version_number} · Control: {policy.related_control_id || "None"} · Audited on {new Date(policy.created_at).toLocaleDateString()}
                          </span>
                        </div>
                      </div>
                      <Link
                        to={`/policy/${policy.policy_id}/review`}
                        className="btn btn-secondary btn-sm"
                        style={{ display: "inline-flex", alignItems: "center", gap: 4, textDecoration: "none" }}
                      >
                        <Eye size={12} /> View Details
                      </Link>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

// Use: Inbox page listing all policy drafts submitted to the current approver for review.

import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { api } from "../../lib/api";
import { PageShell } from "../../components/shared/PageShell";
import { FileText, Clock, AlertCircle, CheckCircle, ChevronRight, Eye } from "lucide-react";

type Policy = {
  policy_id: string;
  policy_name: string;
  version_number: number;
  policy_status: string;
  related_control_id?: string | null;
  created_at: string;
};

export default function Inbox() {
  const [policies, setPolicies] = useState<Policy[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function load() {
      try {
        const { data } = await api.get("/api/v1/policies");
        // List all policies that are submitted/pending approval
        setPolicies(Array.isArray(data) ? data : []);
      } catch (err) {
        console.error("Failed to load policy inbox", err);
      } finally {
        setLoading(false);
      }
    }
    void load();
  }, []);

  const pendingPolicies = policies.filter(
    (p) => p.policy_status === "pending_approval" || p.policy_status === "draft"
  );

  const getStatusStyle = (status: string) => {
    switch (status.toLowerCase()) {
      case "approved":
        return { bg: "#ECFDF5", text: "#10B981" };
      case "rejected":
        return { bg: "#FEF2F2", text: "#EF4444" };
      case "pending_approval":
      case "submitted":
        return { bg: "#FFFBEB", text: "#F59E0B" };
      default:
        return { bg: "#F3F4F6", text: "#6B7280" };
    }
  };

  return (
    <div className="page-panel">
      <PageShell title="Policy Inbox" context="Verify and approve generated organizational policies." />

      {loading ? (
        <p style={{ marginTop: 20 }}>Loading policy queue…</p>
      ) : (
        <div style={{ marginTop: 24, display: "flex", flexDirection: "column", gap: 16 }}>
          <div className="card" style={{ padding: 20 }}>
            <h3 style={{ marginTop: 0, marginBottom: 16, display: "flex", alignItems: "center", gap: 8 }}>
              <Clock size={18} color="var(--primary)" /> Pending Sign-off Queue ({pendingPolicies.length})
            </h3>

            {pendingPolicies.length === 0 ? (
              <p style={{ color: "var(--muted)", margin: 0, fontSize: 13 }}>
                No policies currently awaiting review.
              </p>
            ) : (
              <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
                {pendingPolicies.map((policy) => {
                  const style = getStatusStyle(policy.policy_status);
                  return (
                    <div
                      key={policy.policy_id}
                      style={{
                        border: "1px solid var(--border)",
                        borderRadius: 10,
                        padding: 16,
                        display: "flex",
                        justifyContent: "space-between",
                        alignItems: "center",
                        transition: "all 0.2s",
                        background: "var(--surface)",
                      }}
                    >
                      <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                        <div
                          style={{
                            width: 36,
                            height: 36,
                            borderRadius: 8,
                            backgroundColor: "var(--primary-bg)",
                            display: "flex",
                            alignItems: "center",
                            justifyContent: "center",
                            color: "var(--primary)",
                          }}
                        >
                          <FileText size={18} />
                        </div>
                        <div>
                          <strong style={{ display: "block", fontSize: 14 }}>{policy.policy_name}</strong>
                          <span style={{ fontSize: 12, color: "var(--muted)" }}>
                            v{policy.version_number} · Control: {policy.related_control_id || "None"} · Submitted {new Date(policy.created_at).toLocaleDateString()}
                          </span>
                        </div>
                      </div>
                      <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                        <span
                          className="badge"
                          style={{ backgroundColor: style.bg, color: style.text, fontWeight: 600, fontSize: 11 }}
                        >
                          {policy.policy_status.replace("_", " ").toUpperCase()}
                        </span>
                        <Link
                          to={`/policy/${policy.policy_id}/review`}
                          className="btn btn-secondary btn-sm"
                          style={{ display: "inline-flex", alignItems: "center", gap: 4, textDecoration: "none" }}
                        >
                          <Eye size={12} /> Review Policy <ChevronRight size={12} />
                        </Link>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

// Use: Policy diff and approval workspace. Integrates AI conflict detection and executive summary parallel queries.

import { useEffect, useState } from "react";
import { useParams, useNavigate, Link } from "react-router-dom";
import { api } from "../../lib/api";
import { PageShell } from "../../components/shared/PageShell";
import { 
  Sparkles, 
  CheckCircle, 
  XCircle, 
  AlertTriangle, 
  ArrowLeft,
  RefreshCw,
  TrendingUp
} from "lucide-react";

type Policy = {
  policy_id: string;
  policy_name: string;
  version_number: number;
  policy_status: string;
  related_control_id?: string | null;
  policy_content?: string | null;
  submitted_to?: string | null;
  created_at: string;
};

export default function PolicyReview() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [policy, setPolicy] = useState<Policy | null>(null);
  const [loading, setLoading] = useState(true);

  // AI Analysis States
  const [aiLoading, setAiLoading] = useState(false);
  const [aiError, setAiError] = useState<string | null>(null);
  const [aiSummary, setAiSummary] = useState<string | null>(null);
  const [aiConflicts, setAiConflicts] = useState<string | null>(null);
  const [hasRunAnalysis, setHasRunAnalysis] = useState(false);

  // Decision States
  const [showRejectForm, setShowRejectForm] = useState(false);
  const [rejectionReason, setRejectionReason] = useState("");
  const [decisionLoading, setDecisionLoading] = useState(false);

  async function load() {
    if (!id) return;
    try {
      const { data } = await api.get<Policy>(`/api/v1/policies/${id}`);
      setPolicy(data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    void load();
  }, [id]);

  const handleRunAnalysis = async () => {
    if (!id) return;
    setAiLoading(true);
    setAiError(null);
    try {
      const { data } = await api.post(`/api/v1/ai/policy/analyze/${id}`, {});

      // Separate summary and conflicts responses
      setAiSummary(data.executive_summary?.response || "No summary available.");
      setAiConflicts(data.conflicts?.response || "No conflict analysis returned.");
      setHasRunAnalysis(true);
    } catch (err: any) {
      setAiError(err.response?.data?.detail || "Failed to analyze policy document.");
    } finally {
      setAiLoading(false);
    }
  };

  const handleDecision = async (status: "approved" | "rejected") => {
    if (!id) return;
    setDecisionLoading(true);
    try {
      await api.patch(`/api/v1/policies/${id}`, {
        policy_status: status,
        rejection_reason: status === "rejected" ? rejectionReason : null,
      });
      alert(`Policy ${status} successfully.`);
      navigate("/policy/inbox");
    } catch (err: any) {
      alert(err.response?.data?.detail || "Failed to submit decision.");
    } finally {
      setDecisionLoading(false);
    }
  };

  if (loading) return <div className="page-panel">Loading policy details…</div>;
  if (!policy) return <div className="page-panel">Policy not found.</div>;

  const isPending = policy.policy_status === "pending_approval" || policy.policy_status === "draft";
  const hasConflicts = aiConflicts && (
    aiConflicts.toLowerCase().includes("conflict") || 
    aiConflicts.toLowerCase().includes("contradiction") || 
    aiConflicts.toLowerCase().includes("violation")
  );

  return (
    <div className="page-panel" style={{ paddingBottom: 64 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 12 }}>
        <Link to="/policy/inbox" style={{ color: "var(--muted)", display: "flex", alignItems: "center" }}>
          <ArrowLeft size={16} />
        </Link>
        <PageShell title="Policy Approval Workspace" context={`Reviewing draft of ${policy.policy_name}`} />
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1.2fr 0.8fr", gap: 16, marginTop: 16 }}>
        {/* Left Column: Draft content */}
        <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
          <div className="card" style={{ padding: 24, minHeight: 450, background: "white" }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", borderBottom: "1px solid var(--border)", paddingBottom: 12, marginBottom: 16 }}>
              <div>
                <h3 style={{ margin: 0 }}>{policy.policy_name}</h3>
                <span style={{ fontSize: 12, color: "var(--muted)" }}>
                  Version {policy.version_number} · Control ID: {policy.related_control_id || "Unlinked"}
                </span>
              </div>
              <span className="badge" style={{ textTransform: "uppercase", fontSize: 11, fontWeight: 600 }}>
                {policy.policy_status}
              </span>
            </div>

            <div 
              style={{ 
                whiteSpace: "pre-wrap", 
                fontSize: 14, 
                lineHeight: 1.6, 
                color: "var(--text-primary)", 
                fontFamily: "var(--font-sans)" 
              }}
            >
              {policy.policy_content || "No content has been written in this policy draft yet."}
            </div>
          </div>

          {/* Decision Panel */}
          {isPending && (
            <div className="card" style={{ padding: 20, display: "flex", flexDirection: "column", gap: 16 }}>
              <h4 style={{ margin: 0, fontSize: 14, fontWeight: 600 }}>Approver Decision Panel</h4>

              {showRejectForm ? (
                <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
                  <label style={{ fontSize: 12, fontWeight: 600 }}>Reason for Change Request / Rejection</label>
                  <textarea
                    value={rejectionReason}
                    onChange={(e) => setRejectionReason(e.target.value)}
                    placeholder="Provide specific feedback or missing requirements for the compliance officer..."
                    rows={3}
                    style={{ padding: 8, borderRadius: 6, border: "1px solid var(--border)", width: "100%" }}
                  />
                  <div style={{ display: "flex", gap: 8, alignSelf: "flex-end" }}>
                    <button className="btn btn-secondary btn-sm" onClick={() => setShowRejectForm(false)}>
                      Cancel
                    </button>
                    <button 
                      className="btn btn-primary btn-sm" 
                      onClick={() => handleDecision("rejected")}
                      disabled={decisionLoading || !rejectionReason.trim()}
                      style={{ backgroundColor: "var(--critical)", borderColor: "var(--critical)" }}
                    >
                      Submit Rejection
                    </button>
                  </div>
                </div>
              ) : (
                <div style={{ display: "flex", gap: 12 }}>
                  <button 
                    className="btn btn-primary" 
                    onClick={() => handleDecision("approved")}
                    disabled={decisionLoading}
                    style={{ flex: 1, backgroundColor: "var(--success)", borderColor: "var(--success)", display: "flex", alignItems: "center", justifyContent: "center", gap: 6 }}
                  >
                    <CheckCircle size={16} /> Approve & Sign-off Policy
                  </button>
                  <button 
                    className="btn btn-secondary" 
                    onClick={() => setShowRejectForm(true)}
                    disabled={decisionLoading}
                    style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", gap: 6 }}
                  >
                    <XCircle size={16} /> Request Changes
                  </button>
                </div>
              )}
            </div>
          )}
        </div>

        {/* Right Column: AI Analysis Card */}
        <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
          <div className="card" style={{ padding: 20, display: "flex", flexDirection: "column", gap: 16 }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <h3 style={{ margin: 0, fontSize: 15, display: "flex", alignItems: "center", gap: 6 }}>
                <Sparkles size={16} color="var(--primary)" /> AI Compliance Audit
              </h3>
              {hasRunAnalysis && (
                <button 
                  className="btn btn-ghost btn-sm" 
                  onClick={handleRunAnalysis} 
                  disabled={aiLoading}
                  style={{ fontSize: 11 }}
                >
                  <RefreshCw size={12} style={{ marginRight: 4 }} className={aiLoading ? "spin" : ""} />
                  {aiLoading ? "Analyzing..." : "Re-run"}
                </button>
              )}
            </div>

            {aiLoading ? (
              <div style={{ display: "flex", flexDirection: "column", gap: 12, padding: "16px 0" }}>
                {[90, 75, 80, 50].map((w, i) => (
                  <div key={i} className="skeleton-cell" style={{ height: 14, width: `${w}%`, borderRadius: 4 }} />
                ))}
                <span style={{ fontSize: 12, color: "var(--muted)", fontStyle: "italic", textAlign: "center", marginTop: 8 }}>
                  Checking conflicts and generating summary...
                </span>
              </div>
            ) : aiError ? (
              <div style={{ padding: 12, background: "#FEF2F2", border: "1px solid #FECACA", borderRadius: 8, display: "flex", flexDirection: "column", gap: 10 }}>
                <span style={{ color: "var(--critical)", fontSize: 12 }}>{aiError}</span>
                <button className="btn btn-secondary btn-sm" onClick={handleRunAnalysis} style={{ alignSelf: "flex-start" }}>
                  Retry Analysis
                </button>
              </div>
            ) : !hasRunAnalysis ? (
