          </div>
          <div style={{ marginTop: 12, background: incident.cert_in_reported ? "#ecfdf3" : "#fffbeb", border: `1px solid ${incident.cert_in_reported ? "#86efac" : "#fde68a"}`, borderRadius: 10, padding: 10 }}>
