          </div>
        </div>
        <div style={{ background: "#fff", border: "1px solid #e5e7eb", borderRadius: 12, padding: 16 }}>
          <h3 style={{ marginTop: 0 }}>Actions</h3>
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
