            <div key={`${entry.action_taken}-${index}`} style={{ borderTop: index === 0 ? "0" : "1px solid #f3f4f6", paddingTop: index === 0 ? 0 : 8, marginTop: index === 0 ? 0 : 8 }}>
              <div>{entry.action_taken}</div>
