// Use: Super Admin — Institution Detail view. Shows 3 stat cards and tabs for Users, Departments, and Audit Logs.

import { useState, useEffect } from "react";
import { useParams, Link, useNavigate } from "react-router-dom";
import { api } from "../../lib/api";
import { PageShell } from "../../components/shared/PageShell";
import { ConfirmModal } from "../../components/shared/ConfirmModal";
import { useToast } from "../../components/shared/Toast";
import { Users, Building2, BarChart3, ScrollText } from "lucide-react";

interface Institution {
  institution_id: string;
  institution_name: string;
  institution_type: string;
  city: string;
  state: string;
  staff_count: number;
  is_active: boolean;
  user_count: number;
  department_count: number;
  compliance_percentage: number;
}

interface User {
  user_id: string;
  full_name: string;
  email: string;
  role_name: string;
  is_active: boolean;
  last_login: string | null;
  created_at: string;
}

interface Department {
  department_id: string;
  department_name: string;
  department_code: string | null;
  hod_name: string | null;
  reviewer_name: string | null;
  is_active: boolean;
}

interface AuditLog {
  audit_log_id: string;
  user_name: string;
  action_type: string;
  entity_type: string | null;
  entity_id: string | null;
  ip_address: string | null;
  created_at: string;
}

const ACTION_LABELS: Record<string, string> = {
  login: "Logged in", logout: "Logged out", user_created: "Created user",
  role_changed: "Changed role", login_failed: "Failed login", evidence_approved: "Approved evidence",
  reviewer_assigned: "Assigned reviewer",
};

export default function TenantDetail() {
  const { institution_id } = useParams<{ institution_id: string }>();
  const navigate = useNavigate();
  const toast = useToast();
  const [institution, setInstitution] = useState<Institution | null>(null);
  const [users, setUsers] = useState<User[]>([]);
  const [departments, setDepartments] = useState<Department[]>([]);
  const [auditLogs, setAuditLogs] = useState<AuditLog[]>([]);
  const [activeTab, setActiveTab] = useState<"users" | "departments" | "audit">("users");
  const [loading, setLoading] = useState(true);
  const [confirmDeactivate, setConfirmDeactivate] = useState(false);

  useEffect(() => {
    if (!institution_id) return;
    async function load() {
      setLoading(true);
      try {
        const [instRes, usersRes, deptsRes, auditRes] = await Promise.allSettled([
          api.get(`/api/v1/institutions/${institution_id}`),
          api.get(`/api/v1/users`, { params: { institution_id } }),
          api.get(`/api/v1/departments`),
          api.get(`/api/v1/audit/logs`, { params: { institution_id, limit: 50 } }),
        ]);
        if (instRes.status === "fulfilled") setInstitution(instRes.value.data);
        if (usersRes.status === "fulfilled") setUsers(usersRes.value.data);
        if (deptsRes.status === "fulfilled") setDepartments(deptsRes.value.data);
        if (auditRes.status === "fulfilled") setAuditLogs(auditRes.value.data?.logs ?? []);
      } catch { /* individual handled */ }
      setLoading(false);
    }
    load();
  }, [institution_id]);

  async function handleToggleStatus() {
    if (!institution) return;
    try {
      await api.put(`/api/v1/institutions/${institution_id}/status`, { is_active: !institution.is_active });
      toast.success(`Institution ${institution.is_active ? "deactivated" : "activated"}`);
      setInstitution({ ...institution, is_active: !institution.is_active });
      setConfirmDeactivate(false);
    } catch {
      toast.error("Failed to update status");
    }
  }

  if (loading) {
    return (
      <div style={{ padding: 32 }}>
        {Array.from({ length: 4 }).map((_, i) => (
          <div key={i} className="skeleton" style={{ height: 40, marginBottom: 16, borderRadius: 8 }} />
        ))}
      </div>
    );
  }

  if (!institution) {
    return (
      <div style={{ padding: 32, textAlign: "center", color: "var(--text-muted)" }}>
        <p>Institution not found.</p>
        <Link to="/super-admin/tenants" className="btn btn-primary" style={{ marginTop: 12 }}>← Back to Institutions</Link>
      </div>
    );
  }

  return (
    <PageShell
      title={institution.institution_name}
      subtitle={`${institution.institution_type} — ${institution.city}, ${institution.state}`}
      breadcrumbs={[
        { label: "Institutions", href: "/super-admin/tenants" },
        { label: institution.institution_name },
      ]}
      actions={
        <div style={{ display: "flex", gap: 8 }}>
          <button
            className={`btn ${institution.is_active ? "btn-ghost" : "btn-primary"}`}
            onClick={() => setConfirmDeactivate(true)}
          >
            {institution.is_active ? "Deactivate" : "Activate"}
          </button>
        </div>
      }
    >
      {/* Stat Cards */}
      <div className="stats-grid" style={{ gridTemplateColumns: "repeat(3, 1fr)", marginBottom: 24 }}>
        {[
          { icon: Users, label: "Total Users", value: institution.user_count },
          { icon: Building2, label: "Departments", value: institution.department_count },
          { icon: BarChart3, label: "Compliance Score", value: `${institution.compliance_percentage}%` },
        ].map(({ icon: Icon, label, value }) => (
          <div key={label} className="stat-card">
            <div className="stat-card-icon"><Icon size={20} /></div>
            <div className="stat-card-value">{value}</div>
            <div className="stat-card-label">{label}</div>
          </div>
        ))}
      </div>

      {/* Tabs */}
      <div className="card">
        <div style={{ display: "flex", borderBottom: "1px solid var(--border)", marginBottom: 20 }}>
          {(["users", "departments", "audit"] as const).map((tab) => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`tab-btn ${activeTab === tab ? "active" : ""}`}
              style={{ padding: "10px 20px", background: "none", border: "none", cursor: "pointer", fontSize: 14, fontWeight: activeTab === tab ? 600 : 400, color: activeTab === tab ? "var(--primary)" : "var(--text-secondary)", borderBottom: activeTab === tab ? "2px solid var(--primary)" : "2px solid transparent", marginBottom: -1 }}
            >
              {tab === "users" ? "Users" : tab === "departments" ? "Departments" : "Audit Logs"}
            </button>
          ))}
        </div>

        {/* Users Tab */}
        {activeTab === "users" && (
          <div className="table-wrapper">
            <table className="data-table">
              <thead>
                <tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Last Login</th><th>Created</th></tr>
              </thead>
              <tbody>
                {users.length === 0 ? (
                  <tr><td colSpan={6} style={{ textAlign: "center", color: "var(--text-muted)", padding: 32 }}>No users found.</td></tr>
                ) : users.map((u) => (
                  <tr key={u.user_id}>
                    <td style={{ fontWeight: 500 }}>{u.full_name}</td>
                    <td style={{ fontSize: 13, color: "var(--text-secondary)" }}>{u.email}</td>
                    <td><span className="badge badge-draft">{u.role_name}</span></td>
                    <td><span className={`badge ${u.is_active ? "badge-compliant" : "badge-inactive"}`}>{u.is_active ? "Active" : "Inactive"}</span></td>
                    <td style={{ fontSize: 12, color: "var(--text-muted)" }}>{u.last_login ? new Date(u.last_login).toLocaleDateString("en-IN") : "Never"}</td>
                    <td style={{ fontSize: 12, color: "var(--text-muted)", fontFamily: "var(--font-mono)" }}>{new Date(u.created_at).toLocaleDateString("en-IN")}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {/* Departments Tab */}
        {activeTab === "departments" && (
          <div className="table-wrapper">
            <table className="data-table">
              <thead>
                <tr><th>Department Name</th><th>Code</th><th>HOD Name</th><th>Reviewer Assigned</th><th>Status</th></tr>
              </thead>
              <tbody>
                {departments.length === 0 ? (
                  <tr><td colSpan={5} style={{ textAlign: "center", color: "var(--text-muted)", padding: 32 }}>No departments found.</td></tr>
                ) : departments.map((d) => (
                  <tr key={d.department_id}>
                    <td style={{ fontWeight: 500 }}>{d.department_name}</td>
                    <td><code style={{ fontSize: 12, color: "var(--text-muted)" }}>{d.department_code ?? "—"}</code></td>
                    <td>{d.hod_name ?? "—"}</td>
                    <td style={{ color: d.reviewer_name ? "var(--text-primary)" : "var(--warning)" }}>{d.reviewer_name ?? "Unassigned"}</td>
                    <td><span className={`badge ${d.is_active ? "badge-compliant" : "badge-inactive"}`}>{d.is_active ? "Active" : "Inactive"}</span></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {/* Audit Logs Tab */}
        {activeTab === "audit" && (
          <>
            <div className="table-wrapper">
              <table className="data-table">
                <thead>
                  <tr><th>Timestamp</th><th>User</th><th>Action</th><th>Entity</th><th>IP</th></tr>
                </thead>
                <tbody>
                  {auditLogs.length === 0 ? (
                    <tr><td colSpan={5} style={{ textAlign: "center", color: "var(--text-muted)", padding: 32 }}>No logs for this institution.</td></tr>
                  ) : auditLogs.slice(0, 50).map((log) => (
                    <tr key={log.audit_log_id}>
                      <td style={{ fontSize: 11, fontFamily: "var(--font-mono)", color: "var(--text-muted)" }}>{new Date(log.created_at).toLocaleString("en-IN")}</td>
                      <td style={{ fontSize: 13 }}>{log.user_name ?? "System"}</td>
                      <td><span className="badge badge-draft">{ACTION_LABELS[log.action_type] ?? log.action_type}</span></td>
                      <td style={{ fontSize: 12, color: "var(--text-muted)" }}>{log.entity_type ?? "—"}</td>
                      <td style={{ fontSize: 11, fontFamily: "var(--font-mono)", color: "var(--text-muted)" }}>{log.ip_address ?? "—"}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            <div style={{ marginTop: 12 }}>
              <Link to={`/super-admin/audit-trail?institution_id=${institution_id}`} style={{ fontSize: 12, color: "var(--primary)", fontWeight: 600 }}>
                View full audit trail for this institution →
              </Link>
            </div>
          </>
        )}
      </div>

      <ConfirmModal
        open={confirmDeactivate}
        title={institution.is_active ? "Deactivate Institution" : "Activate Institution"}
        description={institution.is_active
          ? `Deactivating will prevent all users at "${institution.institution_name}" from logging in. Continue?`
          : `This will re-enable access for all users at "${institution.institution_name}". Continue?`}
        confirmLabel={institution.is_active ? "Deactivate" : "Activate"}
        confirmVariant={institution.is_active ? "destructive" : "default"}
        onConfirm={handleToggleStatus}
        onCancel={() => setConfirmDeactivate(false)}
      />
    </PageShell>
  );
}

// Use: Super Admin — Tenant Manager. List, create, activate/deactivate institutions.

import { useState, useEffect, useCallback } from "react";
import { Link } from "react-router-dom";
import { api } from "../../lib/api";
import { PageShell } from "../../components/shared/PageShell";
import { ConfirmModal } from "../../components/shared/ConfirmModal";
import { useToast } from "../../components/shared/Toast";
import { Plus, Eye, Building2 } from "lucide-react";

interface Institution {
  institution_id: string;
  institution_name: string;
  institution_type: string;
  city: string;
  state: string;
  staff_count: number;
  is_active: boolean;
  created_at: string;
}

const INDIAN_STATES = [
  "Andhra Pradesh","Arunachal Pradesh","Assam","Bihar","Chhattisgarh","Goa","Gujarat",
  "Haryana","Himachal Pradesh","Jharkhand","Karnataka","Kerala","Madhya Pradesh",
  "Maharashtra","Manipur","Meghalaya","Mizoram","Nagaland","Odisha","Punjab",
  "Rajasthan","Sikkim","Tamil Nadu","Telangana","Tripura","Uttar Pradesh",
  "Uttarakhand","West Bengal","Delhi","Jammu and Kashmir","Ladakh","Chandigarh",
  "Puducherry","Lakshadweep","Dadra and Nagar Haveli","Daman and Diu","Andaman and Nicobar Islands"
];

const INST_TYPES = ["University", "College", "Institute"];

interface InstitutionFormData {
  institution_name: string;
  institution_type: string;
  email: string;
  phone: string;
  address: string;
  city: string;
  state: string;
  staff_count: string;
}

const EMPTY_FORM: InstitutionFormData = {
  institution_name: "", institution_type: "University", email: "",
  phone: "", address: "", city: "", state: "", staff_count: "",
};

export default function Tenants() {
  const toast = useToast();
  const [institutions, setInstitutions] = useState<Institution[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("All");
  const [typeFilter, setTypeFilter] = useState("All");
  const [stateFilter, setStateFilter] = useState("All");

  // Modal state
  const [showModal, setShowModal] = useState(false);
  const [modalLoading, setModalLoading] = useState(false);
  const [form, setForm] = useState<InstitutionFormData>(EMPTY_FORM);
  const [formErrors, setFormErrors] = useState<Partial<InstitutionFormData>>({});

  // Confirm modal
  const [confirmTarget, setConfirmTarget] = useState<Institution | null>(null);

  const fetchInstitutions = useCallback(async () => {
    setLoading(true);
    try {
      const params: Record<string, string> = {};
      if (search) params.search = search;
      if (statusFilter !== "All") params.status = statusFilter;
      if (typeFilter !== "All") params.type = typeFilter;
      if (stateFilter !== "All") params.state = stateFilter;
      const res = await api.get("/api/v1/institutions", { params });
      setInstitutions(res.data);
    } catch {
      toast.error("Failed to load institutions");
    }
    setLoading(false);
  }, [search, statusFilter, typeFilter, stateFilter]);

  useEffect(() => { fetchInstitutions(); }, [fetchInstitutions]);

  function validateForm(): boolean {
    const errors: Partial<InstitutionFormData> = {};
    if (!form.institution_name.trim()) errors.institution_name = "Name is required";
    if (!form.city.trim()) errors.city = "City is required";
    if (!form.state) errors.state = "State is required";
    setFormErrors(errors);
    return Object.keys(errors).length === 0;
  }

  async function handleCreate() {
    if (!validateForm()) return;
    setModalLoading(true);
    try {
      await api.post("/api/v1/institutions", {
        ...form,
        staff_count: form.staff_count ? parseInt(form.staff_count) : 0,
      });
      toast.success("Institution created successfully");
      setShowModal(false);
      setForm(EMPTY_FORM);
      fetchInstitutions();
    } catch (err: any) {
      toast.error(err?.response?.data?.detail ?? "Failed to create institution");
    }
    setModalLoading(false);
  }

  async function handleToggleStatus() {
    if (!confirmTarget) return;
    try {
      await api.put(`/api/v1/institutions/${confirmTarget.institution_id}/status`, {
        is_active: !confirmTarget.is_active,
      });
      toast.success(`Institution ${confirmTarget.is_active ? "deactivated" : "activated"} successfully`);
      setConfirmTarget(null);
      fetchInstitutions();
    } catch {
      toast.error("Failed to update status");
    }
  }

  return (
    <PageShell
      title="Institutions"
      subtitle="Manage all registered tenants on the platform"
      actions={
        <button className="btn btn-primary" onClick={() => setShowModal(true)} style={{ display: "flex", alignItems: "center", gap: 6 }}>
          <Plus size={15} /> Add Institution
        </button>
      }
    >
      {/* Filter Row */}
      <div className="filter-bar" style={{ display: "flex", gap: 10, flexWrap: "wrap", marginBottom: 20 }}>
        <input
          className="form-input"
          placeholder="Search by name or city..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          style={{ flex: 1, minWidth: 200, fontSize: 13 }}
        />
        <select className="form-input" value={typeFilter} onChange={(e) => setTypeFilter(e.target.value)} style={{ fontSize: 13, minWidth: 130 }}>
          <option value="All">All Types</option>
          {INST_TYPES.map((t) => <option key={t}>{t}</option>)}
        </select>
        <select className="form-input" value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)} style={{ fontSize: 13, minWidth: 120 }}>
          <option value="All">All Status</option>
          <option value="Active">Active</option>
          <option value="Inactive">Inactive</option>
        </select>
        <select className="form-input" value={stateFilter} onChange={(e) => setStateFilter(e.target.value)} style={{ fontSize: 13, minWidth: 150 }}>
          <option value="All">All States</option>
          {INDIAN_STATES.map((s) => <option key={s}>{s}</option>)}
        </select>
      </div>

      {/* Table */}
      <div className="card">
        <div className="table-wrapper">
          <table className="data-table">
            <thead>
              <tr>
                <th>Name</th><th>Type</th><th>City, State</th><th>Staff</th><th>Status</th><th>Created</th><th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {loading ? (
                Array.from({ length: 5 }).map((_, i) => (
                  <tr key={i}>
                    {Array.from({ length: 7 }).map((_, j) => (
                      <td key={j}><div className="skeleton" style={{ height: 18, borderRadius: 4 }} /></td>
                    ))}
                  </tr>
                ))
              ) : institutions.length === 0 ? (
                <tr>
                  <td colSpan={7} style={{ textAlign: "center", padding: "48px 16px" }}>
                    <Building2 size={36} style={{ color: "var(--text-muted)", marginBottom: 10, display: "block", margin: "0 auto 10px" }} />
                    <p style={{ color: "var(--text-muted)", margin: 0, fontSize: 14 }}>No institutions found.</p>
                  </td>
                </tr>
              ) : institutions.map((inst) => (
                <tr key={inst.institution_id}>
                  <td>
                    <Link to={`/super-admin/tenants/${inst.institution_id}`} style={{ fontWeight: 600, color: "var(--primary)" }}>
                      {inst.institution_name}
                    </Link>
                  </td>
                  <td><span className="badge badge-draft">{inst.institution_type}</span></td>
                  <td style={{ color: "var(--text-secondary)", fontSize: 13 }}>{inst.city}, {inst.state}</td>
                  <td>{inst.staff_count ?? "—"}</td>
                  <td>
                    <span className={`badge ${inst.is_active ? "badge-compliant" : "badge-inactive"}`}>
                      {inst.is_active ? "Active" : "Inactive"}
                    </span>
                  </td>
                  <td style={{ fontSize: 12, color: "var(--text-muted)", fontFamily: "var(--font-mono)" }}>
                    {new Date(inst.created_at).toLocaleDateString("en-IN")}
                  </td>
                  <td>
                    <div style={{ display: "flex", gap: 6 }}>
                      <Link to={`/super-admin/tenants/${inst.institution_id}`} className="btn btn-ghost" style={{ padding: "4px 10px", fontSize: 12, display: "flex", alignItems: "center", gap: 4 }}>
                        <Eye size={12} /> View
                      </Link>
                      <button
                        className={`btn ${inst.is_active ? "btn-ghost" : "btn-primary"}`}
                        onClick={() => setConfirmTarget(inst)}
                        style={{ padding: "4px 10px", fontSize: 12 }}
                      >
                        {inst.is_active ? "Deactivate" : "Activate"}
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Add Institution Modal */}
      {showModal && (
        <div className="modal-overlay" onClick={() => setShowModal(false)}>
          <div className="modal" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h2 className="modal-title">Add New Institution</h2>
              <button className="modal-close" onClick={() => setShowModal(false)}>×</button>
            </div>
            <div className="modal-body">
              <div className="grid-2" style={{ gap: 16 }}>
                <div className="form-group" style={{ gridColumn: "1 / -1" }}>
                  <label className="form-label">Institution Name *</label>
                  <input className={`form-input ${formErrors.institution_name ? "input-error" : ""}`} value={form.institution_name} onChange={(e) => setForm({ ...form, institution_name: e.target.value })} placeholder="e.g. Jaipur National University" />
                  {formErrors.institution_name && <span className="form-error">{formErrors.institution_name}</span>}
                </div>
                <div className="form-group">
                  <label className="form-label">Type *</label>
                  <select className="form-input" value={form.institution_type} onChange={(e) => setForm({ ...form, institution_type: e.target.value })}>
                    {INST_TYPES.map((t) => <option key={t}>{t}</option>)}
                  </select>
                </div>
                <div className="form-group">
                  <label className="form-label">Staff Count</label>
                  <input type="number" className="form-input" value={form.staff_count} onChange={(e) => setForm({ ...form, staff_count: e.target.value })} placeholder="e.g. 500" />
                </div>
                <div className="form-group">
                  <label className="form-label">Email</label>
                  <input type="email" className="form-input" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} placeholder="admin@institution.ac.in" />
                </div>
                <div className="form-group">
                  <label className="form-label">Phone</label>
                  <input className="form-input" value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} placeholder="+91 98765 43210" />
                </div>
                <div className="form-group">
                  <label className="form-label">City *</label>
                  <input className={`form-input ${formErrors.city ? "input-error" : ""}`} value={form.city} onChange={(e) => setForm({ ...form, city: e.target.value })} placeholder="e.g. Jaipur" />
                  {formErrors.city && <span className="form-error">{formErrors.city}</span>}
                </div>
                <div className="form-group">
                  <label className="form-label">State *</label>
                  <select className={`form-input ${formErrors.state ? "input-error" : ""}`} value={form.state} onChange={(e) => setForm({ ...form, state: e.target.value })}>
                    <option value="">Select State</option>
                    {INDIAN_STATES.map((s) => <option key={s}>{s}</option>)}
                  </select>
                  {formErrors.state && <span className="form-error">{formErrors.state}</span>}
                </div>
                <div className="form-group" style={{ gridColumn: "1 / -1" }}>
                  <label className="form-label">Address</label>
                  <textarea className="form-input" value={form.address} onChange={(e) => setForm({ ...form, address: e.target.value })} rows={2} placeholder="Full postal address" />
                </div>
              </div>
            </div>
            <div className="modal-footer">
              <button className="btn btn-ghost" onClick={() => setShowModal(false)}>Cancel</button>
              <button className="btn btn-primary" onClick={handleCreate} disabled={modalLoading}>
                {modalLoading ? "Creating..." : "Create Institution"}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Deactivate Confirm */}
      <ConfirmModal
        open={!!confirmTarget}
        title={confirmTarget?.is_active ? "Deactivate Institution" : "Activate Institution"}
        description={confirmTarget ? (confirmTarget.is_active
          ? `Deactivating will prevent all users at "${confirmTarget.institution_name}" from logging in. Continue?`
          : `This will re-enable access for all users at "${confirmTarget.institution_name}". Continue?`) : ""}
        confirmLabel={confirmTarget?.is_active ? "Deactivate" : "Activate"}
        confirmVariant={confirmTarget?.is_active ? "destructive" : "default"}
        onConfirm={handleToggleStatus}
        onCancel={() => setConfirmTarget(null)}
      />
    </PageShell>
  );
}

// Use: Vendor detail and contract analysis workspace. Shows vendor profile, risk history, and AI contract analyzer drawer.

import { useEffect, useState } from "react";
import { useParams, useNavigate, Link } from "react-router-dom";
import { api } from "../../lib/api";
import { PageShell } from "../../components/shared/PageShell";
import { AIPanel } from "../../components/shared/AIPanel";
import { CitationChip } from "../../components/shared/CitationChip";
import {
  Sparkles,
  ArrowLeft,
  Building2,
  MapPin,
  FileCheck,
  AlertTriangle,
  CheckCircle,
  RefreshCw,
  Shield,
  Clock,
} from "lucide-react";

import { useApi } from "../../hooks/useApi";
import Loading from "../../components/shared/Loading";
import ErrorState from "../../components/shared/ErrorState";

type RiskAssessment = {
  vendor_risk_id: string;
  risk_level: string;
  assessment_summary?: string | null;
  recommendations?: string | null;
  dpdp_compliant?: boolean | null;
  created_at?: string | null;
};

type Vendor = {
  vendor_id: string;
  vendor_name: string;
  product_name?: string | null;
  vendor_category?: string | null;
  processing_location?: string | null;
  dpa_available: boolean;
  model_training_allowed: boolean;
  contract_expiry_date?: string | null;
  contact_email?: string | null;
  created_at?: string | null;
  risk_assessments: RiskAssessment[];
};

const RISK_COLORS: Record<string, string> = {
  critical: "#EF4444",
  high: "#F97316",
  medium: "#F59E0B",
  low: "#10B981",
};

export default function VendorDetail() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [vendor, setVendor] = useState<Vendor | null>(null);
  const { data, loading, error, refetch } = useApi(async () => {
    if (!id) return null as any;
    const res = await api.get<Vendor>(`/api/v1/vendors/${id}`);
    return res.data as Vendor;
  }, [id]);

  // Contract Analyzer AI drawer
  const [analyzerOpen, setAnalyzerOpen] = useState(false);
  const [contractText, setContractText] = useState("");
  const [aiLoading, setAiLoading] = useState(false);
  const [aiError, setAiError] = useState<string | null>(null);
  const [aiResult, setAiResult] = useState<any>(null);
  const [lastRunAt, setLastRunAt] = useState<string | null>(null);

  useEffect(() => {
    if (!data) return;
    setVendor(data as Vendor | null);
  }, [data]);

  const handleAnalyzeContract = async () => {
    if (!id || !contractText.trim()) return;
    setAiLoading(true);
    setAiError(null);
    try {
      const { data } = await api.post("/api/v1/ai/vendor/analyze-contract", {
        vendor_id: id,
        contract_text: contractText,
      });
      setAiResult(data);
      setLastRunAt(new Date().toLocaleTimeString());
    } catch (err: any) {
      setAiError(err.response?.data?.detail || "Failed to analyze contract.");
    } finally {
      setAiLoading(false);
    }
  };

  if (loading) return <div className="page-panel"><Loading /></div>;
  if (error) return <div className="page-panel"><ErrorState message={error.message} onRetry={() => void refetch()} /></div>;
  if (!vendor) return <div className="page-panel">Vendor not found.</div>;

  const latestRisk = vendor.risk_assessments[0];
  const riskColor = latestRisk?.risk_level ? RISK_COLORS[latestRisk.risk_level] || "#6B7280" : "#6B7280";

  const isExpiringSoon = vendor.contract_expiry_date
    ? new Date(vendor.contract_expiry_date).getTime() - Date.now() < 90 * 24 * 3600 * 1000
    : false;

  return (
    <PageShell
      title={vendor.vendor_name}
      subtitle="Vendor contract analysis and compliance assessment workspace."
      breadcrumbs={[
        { label: "Vendors", href: "/vendor/dashboard" },
        { label: vendor.vendor_name }
      ]}
    >
      <div className="page-panel" style={{ paddingBottom: 64 }}>
        <div style={{ display: "grid", gridTemplateColumns: "1.1fr 0.9fr", gap: 16 }}>
        {/* Left: Vendor profile */}
        <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
          <div className="card" style={{ padding: 24 }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 20 }}>
              <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                <div style={{ width: 48, height: 48, borderRadius: 12, background: "var(--primary-bg)", display: "flex", alignItems: "center", justifyContent: "center" }}>
                  <Building2 size={24} color="var(--primary)" />
                </div>
                <div>
                  <h3 style={{ margin: 0 }}>{vendor.vendor_name}</h3>
                  <span style={{ fontSize: 13, color: "var(--muted)" }}>{vendor.product_name || "No product specified"}</span>
                </div>
              </div>
              {latestRisk && (
                <span className="badge" style={{ backgroundColor: `${riskColor}1A`, color: riskColor, fontWeight: 700, fontSize: 12 }}>
                  {latestRisk.risk_level.toUpperCase()} RISK
                </span>
              )}
            </div>

            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
              {[
                { label: "Category", value: vendor.vendor_category || "—" },
                { label: "Processing Location", value: vendor.processing_location || "—" },
                { label: "Contact", value: vendor.contact_email || "—" },
                { label: "Contract Expiry", value: vendor.contract_expiry_date ? new Date(vendor.contract_expiry_date).toLocaleDateString() : "—" },
              ].map(({ label, value }) => (
                <div key={label} style={{ padding: 12, background: "var(--surface-raised)", borderRadius: 8 }}>
                  <div style={{ fontSize: 11, color: "var(--muted)", fontWeight: 600, textTransform: "uppercase" }}>{label}</div>
                  <div style={{ fontSize: 14, marginTop: 4, fontWeight: 500 }}>{value}</div>
                </div>
              ))}
            </div>

            <div style={{ marginTop: 16, display: "flex", gap: 12, flexWrap: "wrap" }}>
              <span style={{ display: "inline-flex", alignItems: "center", gap: 6, fontSize: 12, padding: "6px 12px", borderRadius: 20, background: vendor.dpa_available ? "#ECFDF5" : "#FEF2F2", color: vendor.dpa_available ? "#10B981" : "#EF4444", fontWeight: 500 }}>
                {vendor.dpa_available ? <CheckCircle size={12} /> : <AlertTriangle size={12} />}
                DPA {vendor.dpa_available ? "Available" : "Missing"}
              </span>
              <span style={{ display: "inline-flex", alignItems: "center", gap: 6, fontSize: 12, padding: "6px 12px", borderRadius: 20, background: vendor.model_training_allowed ? "#FEF2F2" : "#ECFDF5", color: vendor.model_training_allowed ? "#EF4444" : "#10B981", fontWeight: 500 }}>
                <Shield size={12} />
                Model Training {vendor.model_training_allowed ? "Allowed" : "Prohibited"}
              </span>
              {isExpiringSoon && (
                <span style={{ display: "inline-flex", alignItems: "center", gap: 6, fontSize: 12, padding: "6px 12px", borderRadius: 20, background: "#FFFBEB", color: "#D97706", fontWeight: 500 }}>
                  <Clock size={12} /> Contract Expiring Soon
                </span>
              )}
            </div>
          </div>

          {/* Risk Assessment History */}
          <div className="card" style={{ padding: 20 }}>
            <h4 style={{ margin: "0 0 16px 0", fontSize: 14 }}>Risk Assessment History</h4>
            {vendor.risk_assessments.length === 0 ? (
              <p style={{ color: "var(--muted)", fontSize: 13, margin: 0 }}>No formal risk assessments recorded yet.</p>
            ) : (
              <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
                {vendor.risk_assessments.map((ra) => (
                  <div key={ra.vendor_risk_id} style={{ border: "1px solid var(--border)", borderRadius: 10, padding: 14 }}>
                    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
                      <span className="badge" style={{ backgroundColor: `${RISK_COLORS[ra.risk_level] || "#6B7280"}1A`, color: RISK_COLORS[ra.risk_level] || "#6B7280", fontWeight: 600, fontSize: 11 }}>
                        {ra.risk_level?.toUpperCase() || "UNKNOWN"} RISK
                      </span>
                      <span style={{ fontSize: 11, color: "var(--muted)" }}>
                        {ra.created_at ? new Date(ra.created_at).toLocaleDateString() : "—"}
                      </span>
                    </div>
                    {ra.assessment_summary && (
                      <p style={{ fontSize: 12, color: "var(--text-secondary)", margin: "0 0 8px 0", lineHeight: 1.5 }}>
                        {ra.assessment_summary}
                      </p>
                    )}
                    {ra.recommendations && (
                      <p style={{ fontSize: 12, color: "var(--muted)", margin: 0, fontStyle: "italic" }}>
                        Recommendations: {ra.recommendations}
                      </p>
                    )}
                    <div style={{ marginTop: 8, display: "flex", alignItems: "center", gap: 6 }}>
                      {ra.dpdp_compliant === true && <CheckCircle size={12} color="var(--success)" />}
                      {ra.dpdp_compliant === false && <AlertTriangle size={12} color="var(--critical)" />}
                      <span style={{ fontSize: 11, color: "var(--muted)" }}>
                        DPDP: {ra.dpdp_compliant === true ? "Compliant" : ra.dpdp_compliant === false ? "Non-compliant" : "Not assessed"}
                      </span>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Right: AI Contract Analyzer trigger */}
        <div className="card" style={{ padding: 24, display: "flex", flexDirection: "column", gap: 20 }}>
          <div>
            <h3 style={{ margin: "0 0 8px 0", display: "flex", alignItems: "center", gap: 8 }}>
              <Sparkles size={18} color="var(--primary)" /> Contract Compliance Analyzer
            </h3>
            <p style={{ margin: 0, fontSize: 13, color: "var(--muted)", lineHeight: 1.5 }}>
              Paste vendor contract text to run an AI-powered DPDP Act 2023 and ISO 27001 compliance check. Identifies data processing obligations, liability gaps, and missing clauses.
            </p>
          </div>

          <div style={{ background: "var(--surface-raised)", borderRadius: 10, padding: 16, display: "flex", flexDirection: "column", gap: 8 }}>
            <div style={{ fontSize: 12, fontWeight: 600, color: "var(--text-secondary)" }}>The analyzer will check for:</div>
            {[
              "Data processing agreement clauses",
              "DPDP Act obligations and consent provisions",
              "Data breach notification requirements",
              "Sub-processor disclosure requirements",
              "Data retention and deletion policies",
              "Liability and indemnification gaps",
            ].map((item) => (
              <div key={item} style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 12, color: "var(--text-secondary)" }}>
                <CheckCircle size={12} color="var(--success)" />
                {item}
              </div>
            ))}
          </div>

          <button
            className="btn btn-primary"
            onClick={() => setAnalyzerOpen(true)}
            style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 8 }}
          >
            <Sparkles size={16} /> Open Contract Analyzer
          </button>

          {latestRisk && (
            <div style={{ borderTop: "1px solid var(--border)", paddingTop: 16 }}>
              <div style={{ fontSize: 12, fontWeight: 600, color: "var(--muted)", marginBottom: 8 }}>LATEST RISK VERDICT</div>
              <div style={{ fontSize: 13, color: "var(--text-secondary)", lineHeight: 1.5 }}>
                {latestRisk.assessment_summary || "No summary available."}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Contract Analyzer AI Drawer */}
      <AIPanel
        open={analyzerOpen}
        onClose={() => setAnalyzerOpen(false)}
        title="Contract Compliance Analysis"
        loading={aiLoading}
        error={aiError}
        onRetry={handleAnalyzeContract}
        hasResult={!!aiResult}
        emptyTitle="Paste Contract Text"
        emptyDescription="Provide the full or partial contract text to run AI-powered compliance checks against DPDP Act 2023, ISO 27001, and standard DPA requirements."
        emptyActionLabel="Analyze Contract"
        onEmptyAction={contractText.trim().length >= 100 ? handleAnalyzeContract : undefined}
        lastRunAt={lastRunAt}
        onRegenerate={handleAnalyzeContract}
        regenerateLoading={aiLoading}
      >
        {!aiResult ? (
          <div style={{ display: "flex", flexDirection: "column", gap: 12, width: "100%" }}>
            <label style={{ fontSize: 12, fontWeight: 600, color: "var(--text-secondary)" }}>
              Contract text or clause extract
            </label>
            <textarea
              style={{
                width: "100%",
                minHeight: 200,
                padding: 10,
                borderRadius: "var(--radius-md)",
                border: "1px solid var(--border)",
                background: "var(--surface)",
                color: "var(--text-primary)",
                fontFamily: "monospace",
                fontSize: 12,
                resize: "vertical",
              }}
              placeholder="Paste the contract text, DPA clauses, or data processing agreement sections here... (min 100 characters)"
              value={contractText}
              onChange={(e) => setContractText(e.target.value)}
              maxLength={5000}
            />
            <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11, color: "var(--muted)" }}>
              <span>Minimum 100 characters required</span>
              <span>{contractText.length} / 5000</span>
            </div>
            <button
              className="btn btn-primary"
              onClick={handleAnalyzeContract}
              disabled={contractText.trim().length < 100 || aiLoading}
              style={{ alignSelf: "flex-end", display: "flex", alignItems: "center", gap: 6 }}
            >
              <Sparkles size={14} /> Analyze Contract
            </button>
          </div>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <span style={{ fontSize: 12, fontWeight: 600, color: "var(--success)", display: "flex", alignItems: "center", gap: 4 }}>
                <CheckCircle size={14} /> Analysis Complete
              </span>
              <button className="btn btn-ghost btn-sm" onClick={() => setAiResult(null)} style={{ fontSize: 11 }}>
                New Analysis
              </button>
            </div>

            {/* Render citations */}
            {Array.isArray(aiResult.citations) && aiResult.citations.length > 0 && (
              <div style={{ display: "flex", flexWrap: "wrap", gap: 4 }}>
                {aiResult.citations.map((c: string, i: number) => (
                  <CitationChip key={i} framework={c} />
                ))}
              </div>
            )}

            {/* Analysis content */}
            <div style={{ whiteSpace: "pre-wrap", fontSize: 13, lineHeight: 1.6, color: "var(--text-primary)" }}>
              {aiResult.response}
            </div>

            <div style={{ fontSize: 11, color: "var(--muted)", fontStyle: "italic" }}>
              Contract analysis is AI-generated. Verify critical legal interpretations with your data privacy counsel before relying on findings.
            </div>
          </div>
        )}
      </AIPanel>
    </div>
  </PageShell>
);
}
